window.__T__=[{"i":9960,"text":"以提供的参考图像作为 Sims 4 角色基础，将其转换为逼真的 {argument name=\"photo style\" default=\"CCD 数码相机闪光灯照片\"}，而非游戏截图。将角色调整为近距离手持自拍姿势，身穿 {argument name=\"outfit\" default=\"纯白色卫衣\"}，一只手臂伸向镜头，另一只手比出大拇指。将场景更改为 {argument name=\"new setting\" default=\"夜间游乐园或嘉年华\"}，呈现强烈的机顶闪光灯效果、略显生硬的高光、低光噪点、轻微模糊以及怀旧的卡片机色彩。添加充满节日氛围的背景，包括红地毯步道、条纹嘉年华摊位、发光的灯箱灯泡、串灯、树木，以及正好 6 个可见的气球：左侧 4 个分别为紫色、绿色、绿色和黄色，右侧 2 个分别为蓝色和红色。保留参考图中遮挡面部的方形马赛克，但使整体图像看起来像是一张真实的随手拍照片，而非渲染场景。","imgs":["https://r2.qqsrc.com/images/originals/17898.jpg"]},{"i":9961,"text":"{\"type\":\"咖啡品牌竖版商业海报\",\"brand\":\"{argument name=\\\"brand name\\\" default=\\\"Dunkin\\\"}\",\"aspect_ratio\":\"4:5\",\"style\":\"超精细高级广告合成，电影级产品摄影与 3D 排版结合，光泽感的橙棕色调，充满活力的动感，浅景深，闪烁的颗粒感，漂浮的咖啡豆和甜甜圈碎屑\",\"main_subject\":{\"description\":\"一位面带微笑的咖啡店员工或咖啡师，从胸部以上展示在画面右侧，面部被一个纯中棕色方形占位符遮挡，上方可见深色短卷发，身穿深棕色衬衫，佩戴橙粉色肩带的米色围裙\",\"apron_patch_text\":\"{argument name=\\\"apron logo text\\\" default=\\\"DUNKIN'\\\"}\",\"pose\":\"手臂向观众方向伸展，前景中手持一大杯透明塑料冰咖啡\"},\"product\":{\"item\":\"超大透明塑料杯，装满冰咖啡、冰块、冷凝水珠和奶油焦糖漩涡\",\"cup_text\":\"{argument name=\\\"cup logo text\\\" default=\\\"DUNKIN'\\\"}\",\"foreground_position\":\"中心下方前景，尺寸非常大，由一只手握住，手指真实地环绕在杯身\",\"effects\":\"奶油丝带和咖啡飞溅从杯中向上盘旋，形成动态喷泉，伴有迷你甜甜圈、巧克力碎、咖啡豆和亮橙色吸管\"},\"surreal_details\":{\"count\":6,\"items\":[\"杯顶搅动的咖啡飞溅中浮现出一间微型 Dunkin 店铺\",\"多个迷你糖霜甜甜圈环绕着饮料\",\"杯沿附近有一个大型巧克力碎甜甜圈\",\"白色奶油流在空中卷曲\",\"漂浮的烘焙咖啡豆\",\"粉色和橙色的小纸屑\"]},\"background\":{\"color\":\"深饱和的 Dunkin 橙色，带有暖红色渐变\",\"typography\":\"巨大的 3D 织物感字母拼写出品牌部分名称，包括左上角的巨大 D，产品后方高大的 U，以及左侧类似 N/K 的大字\",\"texture\":\"缝合帆布，浮雕边缘，柔和的发光雾气，焦外成像和星光闪烁\"},\"top_badge\":{\"position\":\"顶部中心\",\"text\":\"{argument name=\\\"top badge text\\\" default=\\\"Dunkin\\\"}\",\"style\":\"圆角矩形透明轮廓徽章，配白色字体\"},\"headline\":{\"position\":\"左下角\",\"text\":\"{argument name=\\\"headline text\\\" default=\\\"BREW JOY DAILY\\\"}\",\"style\":\"高瘦的白色无衬线字体，三行堆叠，醒目的海报排版\"},\"bottom_feature_chips\":{\"count\":4,\"position\":\"底部边缘水平排列\",\"style\":\"圆角药丸状按钮，带有细白色轮廓，左侧有小图标，白色标签文字\",\"labels\":[\"新鲜萃取\",\"甜蜜能量\",\"丝滑口感\",\"每日悦享\"]},\"composition\":\"戏剧性的产品优先特写视角，杯子占据中心位置，员工在右侧，标题在左侧，品牌徽章在顶部，功能标签在底部，高对比度和超清晰细节\",\"lighting\":\"温暖的摄影棚灯光，发光的轮廓光，塑料杯上的光泽反射，氛围感闪光\",\"quality\":\"高分辨率，精致的社交媒体广告，除指定标签外无额外文字\"}","imgs":["https://r2.qqsrc.com/images/originals/17899.jpg"]},{"i":9962,"text":"{\"type\":\"充满质感的电影级生存惊悚片海报，带有信息图表条\",\"format\":\"竖版影院单张海报\",\"title_text\":\"{argument name=\\\"movie title\\\" default=\\\"地狱峡谷 (HELL’S CANYON)\\\"}\",\"tagline_top\":\"{argument name=\\\"top tagline\\\" default=\\\"有些地方从不宽恕。蛇河亦是如此。\\\"}\",\"author_credit\":\"{argument name=\\\"author name\\\" default=\\\"作者：SHIRA WIGGLES\\\"}\",\"scene\":{\"setting\":\"位于蛇河 (Snake River) 的地狱峡谷，这是一条狭窄且狂暴的激流峡谷，两侧是高耸的深色岩壁和茂密的常青森林\",\"composition\":\"低角度俯瞰顺流而下的风暴峡谷，红色充气筏位于画面中下部中心，六名戴着头盔和救生衣的漂流者正在奋力划过激流，筏身周围溅起巨大的水花，两侧是嶙峋的悬崖，空气中弥漫着水雾和飞沫，远处的峡谷隐没在朦胧的氛围中\",\"mood\":\"危险、冷酷、真实、原始、生存冒险、不祥且具有纪录片般的真实感\",\"lighting\":\"阴天风暴光线，光束穿过云层形成戏剧性效果，高对比度，冷蓝灰色阴影，湿润岩石的高光\",\"color_palette\":\"去饱和的炭灰色、板岩蓝、深松绿色、白色泡沫、铁锈红标题和漂流筏、柔和的棕褐色字体\",\"style\":\"照片级写实电影海报艺术，做旧字体，戏剧性的好莱坞惊悚片主视觉，细腻的颗粒感，风化印刷质感\"},\"typography\":{\"main_title\":\"巨大的压缩粗体大写字母，呈做旧的深红色，居中于峡谷上方，占据海报上半部分\",\"secondary_text\":\"奶油色和棕褐色压缩无衬线大写字母，略带风化效果\",\"bottom_cta\":\"大字间距的大写字母，写着“即将上映” (COMING SOON)\"},\"layout\":{\"top\":\"标题上方的两行居中标语\",\"center\":\"峡谷上方巨大的红色标题，下方为作者署名，配有细横装饰线\",\"mid_scene\":\"激流漂流动作场景，背景融合影评引语\",\"bottom\":\"危险统计信息图表带，包含六个图标面板，下方为安全警告和上映信息\"},\"review_quotes\":{\"count\":4,\"items\":[{\"position\":\"左上\",\"text\":\"\\\"震撼人心。令人手心出汗的旅程。\\\"\",\"source\":\"– OUTDOOR LIFE\"},{\"position\":\"右上\",\"text\":\"\\\"原始。真实。无情。\\\"\",\"source\":\"– ADVENTURE FILM WEEKLY\"},{\"position\":\"左下\",\"text\":\"\\\"一条河。一个峡谷。绝无容错空间。\\\"\",\"source\":\"– THE GUARDIAN\"},{\"position\":\"右下\",\"text\":\"\\\"惊心动魄且残酷。\\\"\",\"source\":\"– NATIONAL GEO ADVENTURE\"}]},\"central_warning\":{\"icon\":\"白色骷髅与交叉骨\",\"headline\":\"比美国任何其他河流都更致命\"},\"infographic_panels\":{\"count\":6,\"style\":\"底部带有垂直分隔线的棕褐色小线条图标\",\"items\":[{\"icon\":\"警告三角\",\"headline\":\"500+\",\"caption\":\"自 20 世纪 70 年代以来的记录死亡人数\"},{\"icon\":\"救生圈\",\"headline\":\"20–30\",\"caption\":\"每年平均死亡人数\"},{\"icon\":\"日历\",\"headline\":\"100+ 英里\",\"caption\":\"高风险激流河段\"},{\"icon\":\"峡谷地图轮廓\",\"headline\":\"地狱峡谷\",\"caption\":\"北美最深的峡谷\"},{\"icon\":\"大坝溢洪道\",\"headline\":\"大坝泄洪\",\"caption\":\"可在几分钟内变得致命\"},{\"icon\":\"漩涡水流\",\"headline\":\"冰冷水域\",\"caption\":\"几分钟内即可导致失温风险\"}]},\"bottom_text\":{\"warning\":\"{argument name=\\\"bottom warning\\\" default=\\\"敬畏河流。它从不宽恕。\\\"}\",\"subwarning\":\"经验、准备和谨慎是你最好的装备。\",\"release\":\"即将上映\"},\"rendering_instructions\":\"创作一张成品海报，而非样机。确保所有文字清晰且拼写准确。使用逼真的水物理效果、细腻的湿岩石、茂密的松树剪影以及做旧的印刷质感。无边框，无额外标志，无现代 UI 元素。\"}","imgs":["https://r2.qqsrc.com/images/originals/17900.jpg"]},{"i":9963,"text":"创作一张电影级照片写实的颁奖典礼剧照，主角是 {argument name=\"character name\" default=\"John C. Swaggert\"}，一位银发男演员，身穿黑色燕尾服，内搭白色衬衫，系浅银色领带，佩戴白色口袋巾，站在大剧院舞台上优雅的黑金讲台后。他的面部被一个平坦的肤色矩形隐私遮罩覆盖，观众的面部也同样用小的肤色方块遮挡。他左手举起一座精美的大型金色奖杯：一个圆环内嵌维特鲁威人风格的小雕像，圆环上有小圆孔，底座为黑色，上面刻有金色铭牌，写着“THE VITRUVIAN CINEMATIC ACHIEVEMENT AWARD”。讲台正面也用金色衬线字体写着“THE VITRUVIAN CINEMATIC ACHIEVEMENT AWARD”，下方配有金色鹰徽。在他身后，左侧背景悬挂着巨大的美国国旗，右侧是一个大型黑色舞台屏幕，上面用金色衬线字体写着“{argument name=\"event title\" default=\"The 97th Da Vinci Awards\"}”，并配有一个小型金色鹰标。画面中央放置一个黑色麦克风，配以温暖的吊灯灯光、金色的建筑细节、穿透薄雾的聚光灯、身着正式晚礼服的观众虚化鼓掌效果，营造出奢华的爱国晚宴氛围。采用宽幅 4:3 构图，浅景深，真实的镜头透视，浓郁温暖的灯光，清晰的奖杯细节，以及高端广播级活动摄影风格。","imgs":["https://r2.qqsrc.com/images/originals/17902.jpg"]},{"i":9964,"text":"{\"type\":\"分层肖像拼贴杂志封面\",\"format\":\"竖版印刷杂志封面，3:4 纵横比\",\"style\":\"电影级历史编辑写实风格，绘画感照片合成，戏剧性的深褐色与烟灰色调，高级复古杂志设计，清晰的衬线字体，饱经风霜的战时氛围\",\"subject\":{\"character\":\"{argument name=\\\"cover subject\\\" default=\\\"道格拉斯·麦克阿瑟\\\"}\",\"main_portrait\":\"一位年长军事将领的巨大半身侧面肖像，面朝右侧，头戴带有刺绣徽章的卡其色军官大檐帽，佩戴飞行员太阳镜，身穿卡其色军装衬衫，领口别有星形徽章，口中衔着一支向右延伸的玉米芯烟斗；面部被一个平面的不透明中褐色方形遮挡块覆盖\",\"secondary_figure\":\"同一位将领的全身小尺寸形象，站在前景中央，双手叉腰，身穿卡其色制服、腰带、大檐帽和靴子，姿态自信威严；其小尺寸面部同样被一个平面的不透明褐色遮挡块覆盖\",\"background\":\"雾气缭绕的二战沿海港口战场，有登陆艇、海军舰艇、在浅滩和泥泞中行走的士兵，远处有烟雾，阴沉的暴风云，底部边缘有低对比度的剪影\"},\"layout\":{\"masthead\":{\"text\":\"{argument name=\\\"magazine title\\\" default=\\\"NATIONAL REVIEW\\\"}\",\"position\":\"顶部，非常大，奶油色高对比度衬线大写字母，部分位于主肖像帽檐和头部后方\",\"supporting_text_count\":2,\"supporting_text\":[{\"text\":\"2024 年 6 月 10 日\",\"position\":\"左上角，微小的奶油色文字\"},{\"text\":\"$6.99\",\"position\":\"右上角，微小的奶油色文字\"}]},\"text_blocks_count\":6,\"text_blocks\":[{\"text\":\"DOUGLAS\\nMacARTHUR\",\"position\":\"左中\",\"style\":\"大型黑色压缩衬线标题\"},{\"text\":\"定义了一个世纪的\\n将军\",\"position\":\"左中，标题下方\",\"style\":\"深红色衬线副标题\"},{\"text\":\"领导力。\\n勇气。\\n承诺。\",\"position\":\"左中下\",\"style\":\"小型黑色大写堆叠文字，上方带有微小的星形分隔符\"},{\"text\":\"{argument name=\\\"quote\\\" default=\\\"老兵不死，只是凋零。\\\"}\\n—道格拉斯·麦克阿瑟\",\"position\":\"右中\",\"style\":\"白色斜体衬线引语，带有超大号起始引号\"},{\"text\":\"从西点军校\\n到东京湾：\\n服务的一生\",\"position\":\"右中下\",\"style\":\"小型白色大写衬线体，由细水平线和居中的星形符号框起\"},{\"text\":\"信仰。职责。国家。\\n胜利。\",\"position\":\"右下\",\"style\":\"小型白色大写衬线体\"}]},\"composition\":\"巨大的肖像占据了上方三分之二的区域，站立的全身人像与下方中心重叠，战场全景构成了底层。运用分层深度、杂志封面层级、强烈的垂直对齐、细微的颗粒感、磨损的纸张纹理、逼真的织物褶皱以及来自左上方的柔和定向光。\",\"color_palette\":\"陈旧的奶油色字体，卡其色制服，炭灰色烟雾，柔和的棕色泥土，深红色强调文字，温暖的深褐色高光\",\"rendering_instructions\":\"创作一张完整的虚构杂志封面，所有排版清晰易读，除列出的 8 个文本元素外无额外文字，具备逼真的历史军事风格、戏剧性的编辑灯光以及精致的印刷封面外观。\"}","imgs":["https://r2.qqsrc.com/images/originals/17903.jpg"]},{"i":9965,"text":"{\"type\":\"儿童科学百科剖面信息图海报\",\"topic\":\"{argument name=\\\"main title\\\" default=\\\"火山的内部世界\\\"}\",\"language\":\"简体中文标注及正文\",\"style\":\"出版级教育插画，细节丰富的纯手绘水彩与水粉风格，温暖的火山橙色与清澈的天蓝色及绿色景观形成对比，适合儿童阅读，标注布局整洁，空间连贯性高，高分辨率\",\"layout\":{\"canvas\":\"竖版全页海报\",\"main_scene\":\"大型层状火山剖面图，右半部分切开以展示分层岩石地层、中央发光的岩浆通道、分支侧喷口、熔岩流、岩浆房、裂缝、山体下方的地下水和气体\",\"background\":\"蓝天白云，巨大的灰色火山灰柱，火山口处有炽热的橙色喷发，远山、湖泊、森林、飞鸟，以及作为比例尺的小小探险家\",\"title_area\":{\"position\":\"左上角\",\"text\":\"{argument name=\\\"main title\\\" default=\\\"火山的内部世界\\\"}\",\"typography\":\"大号毛笔风格中文字体，第一行黑色，第二行粗体红橙色\"},\"mascot_and_intro\":{\"position\":\"左上方\",\"character\":\"戴着卡其色探险帽、背着背包、穿着靴子的小探险家\",\"speech_bubble\":\"地球内部的能量，通过火山喷发来到地表！\",\"intro_paragraph\":\"火山是地球内部的‘能量出口’。当岩浆冲破地壳的阻挡，就会喷发出熔岩、火山灰和气体，塑造我们的地球。\"},\"numbered_callouts\":{\"count\":11,\"labels\":[{\"number\":1,\"title\":\"火山口\",\"description\":\"岩浆、气体和火山碎屑喷出的主要通道。\",\"position\":\"右上角火山口旁\"},{\"number\":2,\"title\":\"火山锥\",\"description\":\"由多次喷发堆积而成的锥形山体，常见的是层状火山。\",\"position\":\"右侧山坡\"},{\"number\":3,\"title\":\"火山灰云\",\"description\":\"由火山灰、气体和小颗粒石块组成，可飘到很远的地方。\",\"position\":\"右上角火山灰云中\"},{\"number\":4,\"title\":\"熔岩流\",\"description\":\"高温的熔岩沿着山坡流动，冷却后形成新的岩石。\",\"position\":\"左上侧山坡\"},{\"number\":5,\"title\":\"火山碎屑层\",\"description\":\"火山灰、火山弹、浮石等喷发物堆积形成的松散岩层。\",\"position\":\"右侧中部剖面\"},{\"number\":6,\"title\":\"侧喷口\",\"description\":\"岩浆从主通道侧面喷出，形成小型喷发口。\",\"position\":\"右侧山腰小喷发处\"},{\"number\":7,\"title\":\"冷却后的熔岩层\",\"description\":\"流出的熔岩冷却后形成坚硬的岩石层，一层层叠加。\",\"position\":\"左侧内部地层\"},{\"number\":8,\"title\":\"岩浆通道\",\"description\":\"岩浆在地下上升的通道，就像火山的‘烟囱’。\",\"position\":\"中央垂直通道\"},{\"number\":9,\"title\":\"岩浆房\",\"description\":\"岩浆在地下储存的‘大房间’，压力越大，喷发越猛烈。\",\"position\":\"岩浆房左下方\"},{\"number\":10,\"title\":\"地下岩层\",\"description\":\"地壳由多种岩石层组成，记录着地球的历史。\",\"position\":\"右下方地层\"},{\"number\":11,\"title\":\"地热与气体\",\"description\":\"地下的高温和气体推动岩浆上升，也会形成温泉、喷气孔等地热现象。\",\"position\":\"底部温泉与岩浆附近\"}]},\"side_panels\":{\"count\":4,\"items\":[{\"title\":\"你知道吗？\",\"position\":\"左侧中部黄色卡片\",\"content\":\"世界上约有 1500 多座活火山，它们在不断改变着地球的面貌！\"},{\"title\":\"岩浆 vs 熔岩\",\"position\":\"左侧下部绿色卡片\",\"content\":\"岩浆：在地下还没喷出来的炽热岩石，温度可达 700~1200°C。熔岩：喷出地表的岩浆，流动时会逐渐冷却。\",\"includes\":\"两幅小型对比插图\"},{\"title\":\"火山喷发会带来什么？\",\"position\":\"左下角浅黄色卡片\",\"content\":\"列举 3 种影响并配图标：带来适合植物生长的肥沃土壤，形成新的陆地和岛屿，但也可能造成火山灰和熔岩流灾害。\"},{\"title\":\"小小观察家\",\"position\":\"右下角浅黄色卡片\",\"content\":\"火山周围常有丰富的矿物、温泉和独特的生态系统，是地球送给我们的礼物！\",\"includes\":\"放大镜插图\"}]},\"detail_insets\":{\"count\":2,\"items\":[{\"position\":\"右侧中部\",\"shape\":\"圆形放大剖面\",\"content\":\"四个可见层标注：火山灰、火山弹、浮石层、火山灰\"},{\"position\":\"右侧下部\",\"shape\":\"圆形放大剖面\",\"content\":\"棕色与灰色地下岩层的特写\"}]},\"small_figures\":{\"count\":6,\"items\":[\"左上方的一名儿童探险家吉祥物\",\"火山左侧基部三名背着背包、拿着望远镜的小探险家\",\"左下方草丛中的一只狐狸\",\"左侧山谷上方的一只飞鹰\"]}},\"rendering_instructions\":\"创建一张连贯的剖面图，确保每个带编号的箭头都指向正确的火山结构。使岩浆呈现白炽色，带有黄白色高光和橙红色边缘，添加烟雾、火山灰颗粒、熔岩裂缝、逼真的分层岩层，以及带有黄色数字徽章的整洁圆角标注框。保持所有中文字符清晰易读，并像精美的教育书籍页面一样进行排版。\",\"customizable_subject\":\"{argument name=\\\"volcano type\\\" default=\\\"层状火山\\\"}\",\"audience\":\"{argument name=\\\"audience\\\" default=\\\"儿童科学读者\\\"}\",\"color_palette\":\"{argument name=\\\"color palette\\\" default=\\\"温暖的火山橙、大地棕、天空蓝、森林绿、浅黄色标注卡片\\\"}\"}","imgs":["https://r2.qqsrc.com/images/originals/17905.jpg"]},{"i":9966,"text":"{\"type\":\"儿童科普医学信息图海报\",\"topic\":\"{argument name=\\\"headline text\\\" default=\\\"心脏 人体的超级泵\\\"}\",\"subtitle\":\"{argument name=\\\"subtitle text\\\" default=\\\"24 小时不停工作，把血液送到全身！\\\"}\",\"style\":\"出版级可爱科学百科剖面插画，适合儿童，暖色调奶油背景，点缀爱心、星星、云朵和圆角注释框，光泽感 3D 卡通渲染结合简洁的矢量标签，细节丰富，解剖结构友好且不恐怖，中文科普海报排版\",\"main_visual\":{\"subject\":\"人体心脏的大型中心解剖剖面\",\"position\":\"左中位置，占据页面大部分空间\",\"colors\":\"右心和静脉为蓝色（代表缺氧血），左心和动脉为红色（代表富氧血）\",\"details\":\"透明剖面心室、瓣膜、室间隔、厚实的心室壁、红色大动脉弓、蓝色肺动脉、腔静脉管、肺静脉、显示血液流向的白色方向箭头、心室内部的小型红细胞笑脸吉祥物\",\"main_labels_count\":12,\"main_labels\":[\"上腔静脉\",\"肺动脉\",\"右心房\",\"三尖瓣\",\"右心室\",\"下腔静脉\",\"主动脉\",\"肺静脉\",\"左心房\",\"二尖瓣\",\"左心室\",\"室间隔\"]},\"layout\":{\"format\":\"竖版信息图，4:5 比例\",\"top_header\":\"红色大号手写体“心脏”，蓝色“人体的超级泵”，标题旁有小型吉祥物心脏/红细胞角色\",\"right_column\":{\"sections_count\":4,\"sections\":[{\"title\":\"血液循环路线图\",\"position\":\"右上\",\"content\":\"包含心脏、肺部、身体图标以及红蓝箭头的迷你示意图\",\"legend_count\":2,\"legend_labels\":[\"缺氧血\",\"富氧血\"],\"step_count\":4,\"step_labels\":[\"1 缺氧血从全身回到心脏\",\"2 送往肺部交换气体\",\"3 富氧血从肺部到心脏\",\"4 泵送到全身各处\"]},{\"title\":\"1 瓣膜开合\",\"position\":\"中上右\",\"content\":\"两个小型心脏剖面图，展示瓣膜打开和关闭的状态\",\"diagram_count\":2,\"labels\":[\"瓣膜打开 血液流入心室\",\"瓣膜关闭 防止血液倒流\"]},{\"title\":\"2 心肌层结构\",\"position\":\"中右\",\"content\":\"心脏壁的分层特写，配有儿童医生吉祥物\",\"labels_count\":3,\"labels\":[\"心内膜\",\"心肌层（厚实有力）\",\"心外膜\"],\"caption\":\"心肌像强壮的肌肉，收缩时推动血液！\"},{\"title\":\"3 心跳节律\",\"position\":\"下右\",\"content\":\"心电图折线图及简短科普知识\",\"facts_count\":2,\"facts\":[\"正常成年人心率：60~100 次/分\",\"运动时心跳会加快，给身体更多能量！\"]}]},\"bottom_area\":{\"sections_count\":3,\"sections\":[{\"title\":\"颜色小贴士\",\"position\":\"左下\",\"item_count\":2,\"items\":[\"蓝色 = 缺氧血（含氧少）\",\"红色 = 富氧血（含氧多）\"],\"decor\":\"红细胞吉祥物正通过望远镜观察\"},{\"title\":\"知识贴士\",\"position\":\"下中\",\"bullet_count\":5,\"bullets\":[\"心脏像一台不停工作的泵。\",\"左心室肌肉最厚，能把血液送得更远。\",\"瓣膜像小门，只让血液向一个方向流动。\",\"一次心跳（心脏收缩 + 舒张）会推动血液前进。\",\"好习惯让心脏更健康：运动、睡眠、少熬夜！\"]},{\"title\":\"对话气泡\",\"position\":\"右下\",\"text\":\"{argument name=\\\"doctor speech bubble\\\" default=\\\"谢谢你一直认真工作！\\\"}\",\"decor\":\"女医生角色站在可爱的机械心脏泵和微笑的红细胞旁边\"}]},\"left_annotations\":\"从标签到心脏结构的虚线引导线，每个标签下方有简短的中文解释文字\",\"character_elements_count\":5,\"character_elements\":[\"顶部标题附近的小型红细胞吉祥物\",\"心脏腔室和血管内的三个微笑红细胞吉祥物\",\"左下角拿着放大镜的男医生\",\"下中位置展示知识贴士的女医生\",\"右下角的机械心脏泵角色\"]},\"text_rendering\":\"所有可见标签均保持简体中文，清晰易读，配有圆角彩色标签框和虚线标注线\",\"lighting\":\"柔和的光泽高光，干净的阴影，高分辨率印刷级构图\",\"avoid\":\"写实血腥、阴暗的医学教材风格、杂乱且难以辨认的微小文字、英文标签\"}","imgs":["https://r2.qqsrc.com/images/originals/17906.jpg"]},{"i":9967,"text":"{\"type\":\"出版级教育类科学剖面百科海报\",\"topic\":\"{argument name=\\\"海报主题\\\" default=\\\"潜水艇内部结构\\\"}\",\"language\":\"简体中文可见文本\",\"aspect_ratio\":\"3:4 竖版海报\",\"style\":\"色彩丰富的半写实插画风格信息图，适合儿童阅读，包含精细的工程横截面图，整洁的矢量风格标签与手绘风水下背景相结合，高分辨率印刷设计\",\"main_title\":\"{argument name=\\\"标题文本\\\" default=\\\"潜水艇内部大揭秘\\\"}\",\"subtitle\":\"— 深海中的隐形探索者 —\",\"scene\":{\"background\":\"蓝色水下海洋，左上方有阳光射入，伴有气泡、鱼群剪影、底部的海草与珊瑚，标题上方有一个小型潜水艇图标\",\"main_subject\":\"居中的大型侧视潜水艇剖面图，深海军蓝色外壳，右侧有金色螺旋桨，透明的内部舱室展示了管道、水箱、船员、机械设备、铺位、控制面板和鱼雷\",\"character\":\"左上角有一位可爱的海军吉祥物，正指向旁边的导语段落\"},\"layout\":{\"top_intro\":\"一段简短的中文介绍，说明潜水艇可以在水下航行、执行侦察任务、规避攻击以及探索海洋\",\"central_cutaway\":{\"position\":\"中间\",\"description\":\"一个完整的潜水艇横截面，带有 10 个编号标注，通过虚线引线连接\",\"callout_count\":10,\"callouts\":[{\"number\":1,\"label\":\"鱼雷舱\",\"color\":\"red\",\"description\":\"前部鱼雷存储与发射管\"},{\"number\":2,\"label\":\"指挥舱 / 控制室\",\"color\":\"orange-red\",\"description\":\"操作员、导航、通信及监控设备\"},{\"number\":3,\"label\":\"潜望镜与观察系统\",\"color\":\"green\",\"description\":\"指挥塔上方的潜望镜与光学观察桅杆\"},{\"number\":4,\"label\":\"船员休息区\",\"color\":\"yellow\",\"description\":\"铺位及紧凑的睡眠空间\"},{\"number\":5,\"label\":\"厨房与生活区\",\"color\":\"purple\",\"description\":\"用于烹饪和日常生活的厨房与起居空间\"},{\"number\":6,\"label\":\"推进器区域\",\"color\":\"blue\",\"description\":\"后部推进轴、发动机驱动及转向鳍\"},{\"number\":7,\"label\":\"声呐设备区\",\"color\":\"teal\",\"description\":\"用于探测水下目标与地形的声呐设备\"},{\"number\":8,\"label\":\"压载水舱\",\"color\":\"light blue\",\"description\":\"通过注水和排水来控制下潜与上浮的压载水舱\"},{\"number\":9,\"label\":\"电池舱\",\"color\":\"green\",\"description\":\"为潜水艇提供动力的电池舱\"},{\"number\":10,\"label\":\"机舱 / 动力系统\",\"color\":\"orange\",\"description\":\"发动机室、电动机及动力机械\"}]},\"bottom_sections\":{\"section_count\":5,\"sections\":[{\"title\":\"下潜与上浮原理\",\"position\":\"左下\",\"count\":2,\"items\":[\"下潜：打开进水阀，水进入压载水舱，使艇下沉。\",\"上浮：压缩空气将水从压载水舱排出，艇体变轻，慢慢上浮。\"],\"visuals\":\"两个小型侧视潜水艇示意图，带有显示下潜与上浮的箭头\"},{\"title\":\"空气循环系统\",\"position\":\"中下\",\"count\":3,\"items\":[\"新鲜空气（净化后）\",\"吸收二氧化碳与有害气体\",\"舱内空气循环\"],\"visuals\":\"带有中央圆柱形空气净化器和循环箭头的圆角卡片\"},{\"title\":\"细节放大镜\",\"position\":\"右下\",\"count\":2,\"items\":[\"潜望镜操作台\",\"鱼雷装填口\"],\"visuals\":\"两个嵌入式特写面板，一个展示水手操作潜望镜控制台，另一个展示鱼雷装填过程\"},{\"title\":\"知识小贴士\",\"position\":\"左下（图表下方）\",\"count\":1,\"items\":[\"潜水艇在水下航行时依靠声呐‘看’世界，通信通过浮出水面的天线或浮缆装置与海面设备进行。\"],\"visuals\":\"带有灯泡图标的奶油色便签框\"},{\"title\":\"规格参数栏\",\"position\":\"右下页脚\",\"count\":3,\"items\":[\"长度：约 60~100 米\",\"乘员：约 50~90 人\",\"下潜深度：可达 200~500 米以上\"],\"visuals\":\"带有白色潜水艇剪影和三个小图标的细长圆角蓝色页脚\"}]},\"design_details\":{\"typography\":\"大号加粗深海军蓝色中文标题，圆角无衬线标注标签，带有彩色数字圆圈的白色圆角标注卡片\",\"palette\":\"深海蓝、青色、奶油色卡片、橙色与绿色工程点缀、深色外壳配暖色内部照明\",\"quality\":\"清晰易读的信息图，布局平衡，引线准确，细节丰富且亲和力强的教育插画，适合儿童科学读物或课堂海报\"},\"customization\":{\"submarine_name\":\"{argument name=\\\"潜水艇名称\\\" default=\\\"深海探索者\\\"}\",\"audience\":\"{argument name=\\\"目标受众\\\" default=\\\"儿童科学百科读者\\\"}\",\"color_mood\":\"{argument name=\\\"色彩氛围\\\" default=\\\"明亮的蓝色水下教育配色\\\"}\"}}","imgs":["https://r2.qqsrc.com/images/originals/17907.jpg"]},{"i":9968,"text":"{\"type\":\"出版级教育科学百科剖面海报\",\"language\":\"简体中文标签与说明文字\",\"main_title\":\"{argument name=\\\"headline text\\\" default=\\\"霸王龙剖面图解\\\"}\",\"subtitle\":\"{argument name=\\\"subtitle text\\\" default=\\\"地球上最强大的掠食者之一\\\"}\",\"subject\":{\"species\":\"{argument name=\\\"dinosaur species\\\" default=\\\"霸王龙 (Tyrannosaurus rex)\\\"}\",\"pose\":\"大型咆哮侧面恐龙，从左向右行走，张开大嘴，尾巴伸展以保持平衡，一只后腿向前，微小的前肢抬起\",\"style\":\"高度精细的半写实科学插画，复古自然历史百科全书风格，丰富的渲染水彩与水粉质感，清晰的墨线勾勒，温暖的羊皮纸背景\",\"cutaway\":\"左半部分展示外部鳞片皮肤和头骨；右侧及身体中心进行解剖处理，露出骨骼、红色肌肉、肋骨、肺部、心脏、肠道、胃部、肌腱以及具有空间连贯性的横截面腿部肌肉层\",\"skin_color\":\"{argument name=\\\"skin color\\\" default=\\\"橄榄棕色与赭石色鳞片，带有深色条纹\\\"}\",\"anatomy_colors\":\"象牙色骨骼，深红与粉色肌肉，蓝紫色肺部，亮红色心脏，橙棕色消化器官\"},\"layout\":{\"composition\":\"纵向海报布局，恐龙居中，编号标注箭头围绕身体辐射，圆角奶油色卡片内嵌小型图解，背景为森林与火山景观\",\"background\":\"中生代森林，包含针叶树、蕨类植物、岩石溪流、朦胧山脉、远方火山、小型飞行翼龙，温暖阳光，教育博物馆海报氛围\",\"top_left_mascot\":\"小型探险家儿童角色，配有对话气泡：\\\"一起来探索霸王龙的身体秘密吧!\\\"\",\"top_right_fact_card\":{\"title\":\"档案小知识\",\"count\":4,\"items\":[\"名称：霸王龙（Tyrannosaurus rex）\",\"生活年代：白垩纪晚期（约 6800 万年前）\",\"发现地：北美洲\",\"体长：约 12–13 米\",\"体重：约 6–8 吨\"],\"note\":\"在事实旁边绘制一个小型的霸王龙头骨图标\"},\"main_numbered_anatomy_callouts\":{\"count\":10,\"items\":[{\"number\":1,\"label\":\"头骨\",\"description\":\"巨大的头骨、强有力的下颚、厚实的骨骼和强壮的咬合肌\"},{\"number\":2,\"label\":\"牙齿\",\"description\":\"大型圆锥形锯齿状牙齿，配有张开大嘴的圆形特写插图\"},{\"number\":3,\"label\":\"颈部肌肉\",\"description\":\"连接头骨与躯干的厚实颈部肌肉\"},{\"number\":4,\"label\":\"肺部（含气囊）\",\"description\":\"蓝色呼吸系统，配有展示分支气囊和血管的圆形插图\"},{\"number\":5,\"label\":\"心脏\",\"description\":\"肋骨架内的大型红色心脏\"},{\"number\":6,\"label\":\"胃部\",\"description\":\"肋骨后方的胃部及消化腔\"},{\"number\":7,\"label\":\"肋骨与胸腔\",\"description\":\"环绕肺部和器官的拱形象牙色肋骨\"},{\"number\":8,\"label\":\"肠道\",\"description\":\"腹部盘绕的橙色肠道\"},{\"number\":9,\"label\":\"骨盆\",\"description\":\"支撑后肢和尾部的大型髋骨\"},{\"number\":10,\"label\":\"后肢肌肉\",\"description\":\"附着在长腿骨上的强壮红色大腿和小腿肌肉\"}]},\"side_information_cards\":{\"count\":5,\"cards\":[{\"position\":\"lower left upper\",\"title\":\"咬合力有多强？\",\"visuals\":\"小型蓝色汽车旁悬挂着标注 6~8 吨的重物\",\"purpose\":\"解释咬合力对比\"},{\"position\":\"lower left middle\",\"title\":\"短小的前肢有什么用？\",\"visuals\":\"带有爪子和橙色运动箭头的小型前肢特写\",\"purpose\":\"解释短小前肢的可能功能\"},{\"position\":\"lower left bottom\",\"title\":\"体型对比\",\"visuals\":\"人类与霸王龙的剪影对比图，垂直刻度达 4 米，水平刻度达 16 米\",\"purpose\":\"展示体型对比及约 12–13 米的体长\"},{\"position\":\"right middle\",\"title\":\"尾巴如何帮助平衡？\",\"count\":3,\"visuals\":[\"带有红色水平平衡箭头的小型恐龙\",\"带有蓝色箭头的尾部负重行走图解\",\"带有红色箭头的奔跑姿态图解\"],\"purpose\":\"解释尾部平衡作用及奔跑稳定性\"},{\"position\":\"lower right\",\"title\":\"你知道吗？\",\"visuals\":\"小型带羽毛幼年恐龙插画\",\"purpose\":\"关于羽毛和近亲的趣味知识卡片\"}]},\"typography\":\"顶部加粗深海军蓝中文标题，红色丝带副标题，清晰的印刷体中文正文，彩色编号圆圈，纤细的彩色引导线，带有细微投影的圆角奶油色注释卡片\",\"rendering_requirements\":\"确保解剖结构清晰且分层，包含准确的内部结构，保持色彩一致与标签清晰，高分辨率可打印海报，无照片级写实，无 3D 渲染，无现代 UI 界面元素\"}","imgs":["https://r2.qqsrc.com/images/originals/17908.jpg"]},{"i":9969,"text":"{\"type\":\"宽幅社交媒体对比图 / 截图拼贴\",\"canvas\":\"超宽横向图像，白色背景，纵横比约为 2.7:1，呈现为一张展示三个生成分镜结果并排显示的截图\",\"layout\":{\"column_count\":3,\"columns\":[{\"position\":\"左侧三分之一\",\"top_element\":{\"type\":\"圆角黑色气泡提示框\",\"text_color\":\"white\",\"language\":\"日语\",\"text\":\"{argument name=\\\"left prompt text\\\" default=\\\"请精确重现以下场景：一位对现代一无所知的法国文艺复兴时期农民，在收到以下提示词后，凭自由想象在脑海中构思出 15 秒的影像，并将其中的 25 个印象深刻的镜头生成为一张合集图片。这段影像的本质并非特效的堆砌，而是一位杰出艺术家的...\\\"}\",\"shape\":\"大型圆角矩形，下方中心带有一个小向下箭头\"},\"bottom_element\":{\"type\":\"分镜联系表\",\"position\":\"气泡下方\",\"grid\":\"5 列 x 5 行\",\"frame_count\":25,\"labels\":\"每个缩略图左上角带有 1 到 25 的微型白色帧编号\",\"visual_theme\":\"静谧的文艺复兴乡村想象，油画质感的电影化棕褐色与橄榄色调，古老的石墙、农间小路、窗帘、披风人物、拱门、手工制品、远方天空、古朴的欧洲氛围\",\"ui_overlay\":\"左下角带有圆角半透明编辑按钮，右下角带有小型分享/导出图标\"}},{\"position\":\"中间三分之一\",\"top_element\":{\"type\":\"圆角黑色气泡提示框\",\"text_color\":\"white\",\"language\":\"日语\",\"text\":\"{argument name=\\\"center prompt text\\\" default=\\\"请精确重现以下场景：在满天星斗下，一对来自低保真、略带忧郁的波普艺术风格日本动画中的纯真少年少女，在收到以下提示词后，凭自由想象在脑海中构思出 15 秒的影像，并将其中的 25 个印象深刻的镜头生成为一张合集图片。这段影像的...\\\"}\",\"shape\":\"大型圆角矩形，下方中心带有一个小向下箭头\"},\"bottom_element\":{\"type\":\"分镜联系表\",\"position\":\"气泡下方\",\"grid\":\"5 列 x 5 行\",\"frame_count\":25,\"labels\":\"每个缩略图左上角带有 1 到 25 的微型白色帧编号\",\"visual_theme\":\"低保真忧郁波普艺术日本动画，星空下的纯真少年少女，深海军蓝调，发光的星星，河岸倒影，柔和颗粒感，怀旧动画特写，剪影，微光，奇幻的忧郁感\",\"ui_overlay\":\"左下角带有圆角半透明编辑按钮，右下角带有小型分享/导出图标\"}},{\"position\":\"右侧三分之一\",\"top_element\":{\"type\":\"圆角黑色气泡提示框\",\"text_color\":\"white\",\"language\":\"日语\",\"text\":\"{argument name=\\\"right prompt text\\\" default=\\\"请精确重现以下场景：一只住在濑户内海港口老家里的年迈三花猫，在收到以下提示词后，凭自由想象在脑海中构思出 15 秒的影像，并将其中的 25 个印象深刻的镜头生成为一张合集图片。这段影像的本质并非特效的堆砌，而是一位杰出艺术家对宇宙的...\\\"}\",\"shape\":\"大型圆角矩形，下方中心带有一个小向下箭头\"},\"bottom_element\":{\"type\":\"分镜联系表\",\"position\":\"气泡下方\",\"grid\":\"5 列 x 5 行\",\"frame_count\":25,\"labels\":\"每个缩略图左上角带有 1 到 25 的微型白色帧编号\",\"visual_theme\":\"通过年迈三花猫视角看到的濑户内海港口家乡，温暖的海岸日光，榻榻米房间，窗户，渔船，港口水面，狭窄街道，猫咪特写，家庭怀旧感，阳光照耀的海面，柔和的纪录片电影风格\",\"ui_overlay\":\"左下角带有圆角半透明编辑按钮，右下角带有小型分享/导出图标\"}}]},\"overall_details\":{\"total_prompt_bubbles\":3,\"total_storyboard_grids\":3,\"total_thumbnails\":75,\"grid_rounding\":\"每个 25 帧的联系表被裁剪在大型圆角矩形内，缩略图之间带有深色边框\",\"composition\":\"均匀间距，三列水平对齐，提示词气泡位于网格上方，留有干净的白色边距，看起来像是对同一文本生成视频提示词的三种不同解读方向的说明性对比\",\"rendering_style\":\"逼真的截图样机，包含清晰的日语排版、微型电影化缩略图、细微的压缩感柔和度，除三个气泡和分镜 UI 元素外无额外说明文字\"}}","imgs":["https://r2.qqsrc.com/images/originals/17909.jpg"]},{"i":9970,"text":"{\"type\":\"全页日式落地页设计模型\",\"format\":\"长图移动端优先网页截图\",\"brand\":{\"name\":\"{argument name=\\\"brand name\\\" default=\\\"KAKERU STUDIO\\\"}\",\"romanized_subtitle\":\"KAKERU STUDIO\",\"logo\":\"左上角简洁的蓝色抽象 K 标志\"},\"theme\":{\"service\":\"在线公司注册支持服务\",\"visual_style\":\"简洁现代的 SaaS 落地页，友好的日本初创企业美学，圆角卡片，柔和阴影，白色背景搭配亮蓝色点缀，黄色高亮装饰，少量纸屑装饰，英雄区背景为淡雅的城市天际线剪影\",\"palette\":\"皇家蓝、天蓝色、白色、淡灰色、黄色、珊瑚粉\",\"typography\":\"粗体圆角日文无衬线标题，易读紧凑的正文\"},\"layout\":{\"sections\":[{\"title\":\"页眉\",\"position\":\"顶部\",\"count\":3,\"elements\":[\"左上角品牌 Logo 和名称\",\"右上角汉堡菜单图标\",\"蓝色小药丸标签，文字为“完全在线，一站式搞定！”\"]},{\"title\":\"首屏区\",\"position\":\"顶部主区域\",\"count\":2,\"elements\":[\"大型日文标题：{argument name=\\\"headline text\\\" default=\\\"让公司设立更简单、更令人期待！\\\"}\",\"右侧扁平化插画，一名穿着蓝色夹克、黄色裤子的无面商人，手持智能手机和笔记本电脑正在奔跑\"]},{\"title\":\"首屏优势卡片\",\"position\":\"首屏下方\",\"count\":3,\"labels\":[\"完全在线\",\"安心安全\",\"最快 3 天设立\"],\"details\":[\"桌面显示器图标，说明文档准备可在线完成\",\"蓝色盾牌勾选图标，说明由专业团队提供坚实支持\",\"黄色时钟图标，说明最快 3 天即可完成公司设立\"]},{\"title\":\"介绍卡片\",\"position\":\"中上部\",\"count\":1,\"elements\":[\"标题：即使是首次设立公司也能轻松完成！\",\"正文说明分步输入信息即可轻松创建文档\",\"右侧大型笔记本电脑和智能手机 UI 模型\",\"小型盆栽插画\"]},{\"title\":\"数据指标行\",\"position\":\"介绍卡片底部\",\"count\":4,\"labels\":[\"累计用户数 10,000 家以上\",\"客户满意度 98.6%\",\"设立速度 最快 3 天完成登记\",\"服务范围 全国覆盖\"]},{\"title\":\"服务流程\",\"position\":\"中部\",\"count\":3,\"labels\":[\"STEP 1 输入公司信息\",\"STEP 2 文档创建与确认\",\"STEP 3 申请与完成\"],\"details\":[\"带勾选标记的表单文档图标\",\"文档与钢笔图标\",\"纸飞机图标\"]},{\"title\":\"选择 KAKERU STUDIO 的理由\",\"position\":\"中下部\",\"count\":3,\"labels\":[\"完全在线完成\",\"专家提供支持\",\"最快 3 天设立\"],\"details\":[\"女性使用笔记本电脑插画\",\"男性专家持有文档插画\",\"日历与时钟插画\"]},{\"title\":\"客户评价\",\"position\":\"理由下方\",\"count\":1,\"elements\":[\"带有圆形模糊男性头像的评价卡片\",\"大型蓝色引号\",\"关于对全在线操作感到不安，但支持非常细致且快速完成注册的日文评价\",\"客户姓名与职位行\"]},{\"title\":\"主要 CTA 横幅\",\"position\":\"中下部\",\"count\":1,\"elements\":[\"带有纸屑装饰的大型蓝色圆角矩形\",\"标题：{argument name=\\\"cta headline\\\" default=\\\"要不要先免费咨询一下？\\\"}\",\"副标题：专业人员将为您提供细致支持！\",\"宽大的珊瑚粉色按钮，文字为“免费咨询”，带右箭头\",\"黄色小药丸标签，文字为“平日 10:00-18:00\",\"右侧女性使用笔记本电脑插画\"]},{\"title\":\"输入表单示例\",\"position\":\"下部\",\"count\":5,\"labels\":[\"文本输入（默认）\",\"文本输入（聚焦）\",\"下拉选择框\",\"复选框\",\"单选按钮\"],\"details\":[\"白色圆角表单面板\",\"蓝色聚焦输入边框\",\"已勾选的方形复选框\",\"两个单选按钮，其中一个已选中\",\"蓝色下一步按钮，文字为“进入下一步”，带箭头\"]},{\"title\":\"UI 组件库\",\"position\":\"底部附近\",\"count\":3,\"labels\":[\"标签\",\"图标\",\"按钮\"],\"details\":[\"8 个柔和圆角标签，包括：人气 No.1、免费 3 天、在线完成、合同会社、株式会社、个人事业主 OK、全国对应\",\"18 个细线条蓝色图标网格，包括：显示器、智能手机、主页、盾牌、文档、柱状图、用户、地球、勾选、日历、日元、纸飞机、锁\",\"4 种按钮样式：主按钮、图标按钮、幽灵按钮及次要箭头/下载变体\"]},{\"title\":\"服务特色卡片\",\"position\":\"底部页脚上方\",\"count\":3,\"labels\":[\"完全在线完成\",\"专家提供支持\",\"全国各地均可对应\"],\"details\":[\"三个带有小插画和文字的紧凑圆角卡片\"]},{\"title\":\"页脚\",\"position\":\"底部\",\"count\":4,\"elements\":[\"蓝色页脚，包含 Logo 和公司信息\",\"三列页脚链接\",\"社交媒体图标\",\"右侧黄色迷你 CTA 框，带有粉色咨询按钮和营业时间\"]}],\"total_distinct_sections\":13},\"composition\":\"单页长滚动落地页，以一张垂直截图呈现，居中内容列，配有宽敞的圆角白色卡片和一致的间距，所有文字均为日文，无浏览器边框，高保真精致 UI 模型\",\"image_quality\":\"清晰的矢量风格界面，整齐的对齐，柔和的渐变与阴影，专业的转化导向型 LP 设计\",\"customization_notes\":\"保持整体日文密集型落地页结构和精确的计数部分组织，同时允许品牌、标题、CTA 标题和服务重点进行自定义。\",\"service_focus\":\"{argument name=\\\"service focus\\\" default=\\\"在线公司注册支持\\\"}\"}","imgs":["https://r2.qqsrc.com/images/originals/17911.jpg"]},{"i":9971,"text":"{\"type\":\"宽幅手绘日本教育信息图\",\"canvas\":{\"aspectRatio\":\"16:9 横屏\",\"background\":\"暖白色纸张纹理\",\"style\":\"友好的马克笔与水彩手绘风格，草图笔记，清晰易读的日语排版，蓝色/橙色/绿色/红色点缀，圆角框，箭头，小型涂鸦图标\"},\"headline\":{\"text\":\"{argument name=\\\"headline text\\\" default=\\\"你是否还认为『图像生成＝AI 绘画』？\\\"}\",\"position\":\"顶部居中\",\"emphasis\":\"橙色下划线，并对『图像生成＝AI 绘画』进行橙色大号字体强调\"},\"subheadline\":{\"text\":\"{argument name=\\\"subheadline text\\\" default=\\\"这种认知，或许需要更新一下了。\\\"}\",\"position\":\"标题下方\",\"color\":\"蓝色\",\"decorations\":\"小型放射状蓝色笔触\"},\"layout\":{\"mainSections\":{\"count\":3,\"arrangement\":\"中间横向排列三个大型圆角矩形面板，由粗蓝色向右箭头连接\",\"sections\":[{\"title\":\"第一阶段\",\"subtitle\":\"艺术\",\"position\":\"左侧\",\"borderColor\":\"蓝色\",\"content\":\"带框的彩色山水风景插画；标题为 代表的なモデル例 的文本块，包含 3 个要点：Stable Diffusion, DALL-E, Midjourney；底部文字 きれいな絵・世界観・雰囲気をつくる（创作精美的画作、世界观与氛围）\",\"icons\":{\"count\":3,\"descriptions\":[\"小图片图标\",\"画笔\",\"艺术家调色板\"]}},{\"title\":\"第二阶段\",\"subtitle\":\"设计\",\"position\":\"中央\",\"borderColor\":\"绿色\",\"content\":\"模拟网站或海报排版，包含标题 未来を、デザインするか。（设计未来吗。），简短段落文本，按钮 詳しくはこちら →（点击了解详情），文档排版，图片占位符，以及图表元素；标题为 代表的なモデル例 的文本块，包含 2 个要点：GPT-Image-1, Nano Banana Pro/2；底部文字 文字・レイアウト・訴求を組み立てる（构建文字、排版与诉求）\",\"icons\":{\"count\":3,\"descriptions\":[\"T 排版图标\",\"布局网格图标\",\"交叉钢笔或设计工具图标\"]}},{\"title\":\"第三阶段\",\"subtitle\":\"图解・理解\",\"position\":\"右侧\",\"borderColor\":\"红色\",\"content\":\"简单的流程图，顶部为 課題（课题），分支指向 原因、本質（構造）、効果 以及 解決策，配有箭头和一个小型柱状图；标题为 代表的なモデル例 的文本块，包含 1 个要点：GPT-Image-2；底部文字 構造を見せる・意味を伝える・思考を前に進める（展示结构、传达意义、推动思考）\"}]},\"lowerExplanatoryElements\":{\"count\":4,\"items\":[{\"type\":\"黄色圆角标注\",\"position\":\"左下方\",\"text\":\"当文字开始在“图像中发挥功能”的那一刻，AI 图像生成便已超越了“图像”本身。\",\"icon\":\"灯泡\"},{\"type\":\"流程条\",\"position\":\"中右下方\",\"count\":3,\"labels\":[\"观看的图像\",\"阅读的图像\",\"思考的图像\"],\"icons\":[\"眼睛\",\"文档\",\"灯泡\"],\"connectors\":\"蓝色箭头\"},{\"type\":\"加粗陈述\",\"position\":\"底部中央附近\",\"text\":\"现在发生的不仅仅是绘画，而是『思考的可视化』。\",\"emphasis\":\"蓝色手写大号字体 『思考的可视化』，配黄色下划线\"},{\"type\":\"底部丝带标注\",\"position\":\"左下至中央\",\"text\":\"意识到这种变化，你对 AI 应用的看法也会随之改变。\",\"icon\":\"盆栽小芽\"}]},\"characters\":{\"count\":2,\"description\":\"同一位友好的教师角色在右侧出现两次，动漫风格的年轻男性，身穿浅蓝色衬衫，手持指示棒；面部区域刻意用米色矩形遮挡\",\"instances\":[{\"position\":\"右上角\",\"pose\":\"手持指示棒指向标题上方\"},{\"position\":\"右下角\",\"pose\":\"手持指示棒和贴有 メモ（笔记） 标签的绿色笔记本，旁边有对话气泡 一緒に学んでいきましょう!（让我们一起学习吧！）\"}],\"customCharacter\":\"{argument name=\\\"teacher character\\\" default=\\\"棕色头发的年轻男教师，身穿浅蓝色衬衫，手持指示棒，面部被米色方块遮挡\\\"}\"},\"extraDecorations\":{\"count\":4,\"items\":[\"左上角黄色灯泡涂鸦\",\"重要文本周围的小太阳光芒标记\",\"橙色、蓝色和黄色的细手绘下划线\",\"圆角对话气泡轮廓与手绘箭头\"]},\"textRequirements\":\"所有日语文本必须清晰、易读且放置准确；保留手绘草图笔记的质感，同时保持图表简洁且具有教学意义。\",\"theme\":\"{argument name=\\\"main message\\\" default=\\\"AI 图像生成已从艺术演进为设计，进而发展到图解与理解，使图像内的文字具备功能性，并实现思考的可视化。\\\"}\"}","imgs":["https://r2.qqsrc.com/images/originals/17912.jpg"]},{"i":9972,"text":"以 REFERENCE_0 作为构图参考，REFERENCE_1 作为角色/姿势参考，将草图转化为精美、高能量的漫画/动画插图。保持 4 个角色的排列：中间后方是一个巨大的肌肉发达的学生正在展示手臂，左下角是一个白发小个子学生处于蹲伏/动作姿势，右侧是一个苗条的站立学生正在举起拳头，左下角是一个被裁切的粉发震惊特写脸部。将粗糙的彩色草图转换为干净的墨线稿，并配以鲜艳的赛璐珞阴影、强烈的漫画分镜感和夸张的透视效果。在三个全身角色身后添加混乱的爆炸背景，包括橙黄色火花、烟雾、速度线、冲击尖刺和漫画爆炸形状。添加 2 个可见的日语文本元素：左上角的大型音效 {argument name=\"sound effect text\" default=\"カオス!\"} 和右下角的锯齿状对话气泡，内容为 {argument name=\"speech bubble text\" default=\"えぇっ!?\\n私の制服!?\"}。保留 REFERENCE_1 中的校服主题，但将其渲染为成品服装：中间和左侧角色采用薄荷绿毛衣和蓝绿色裙子，右侧角色采用深色修身制服，左下角前景为震惊的特写脸部。采用动态少年喜剧漫画页面风格，使用粗轮廓线、戏剧性的运动线条、饱和的色彩和分层漫画效果。","imgs":["https://r2.qqsrc.com/images/originals/17914.png"]},{"i":9973,"text":"创作一张电影感超广角低角度动作照片，场景位于光线昏暗的 {argument name=\"room type\" default=\"酒店卧室\"} 内，从凌乱的白色床面向上仰拍，{argument name=\"number of people\" default=\"两名\"} 充满活力的 {argument name=\"subjects\" default=\"年轻女性\"} 在床垫上方高高跃起。右侧较大的主体在空中定格，双膝弯曲，双臂张开，露出赤脚，长长的黑发凌乱地向上飞扬，身穿白色无袖短款上衣和浅黄色短裤。左侧较小的主体也在床上跳跃，双臂高举，凌乱的黑发随动作摆动，身穿带有白色蕾丝花边的黄色吊带衫和蓝色牛仔短裤。保持两人的面部模糊或被动作与阴影柔和遮挡，同时强调肢体动作、飞扬的头发和俏皮的活力。使用戏剧性的暖色调酒店灯光：跳跃者身后的明亮背光营造出耀眼的轮廓光、镜头光晕、空气中的尘埃颗粒以及强烈的剪影；两侧床头灯发出温暖的光芒，右侧有窗帘，左侧墙上有装裱的画作，深色床头板，凌乱的白色床单，前景中有大枕头。相机视角需极度贴近床面，采用 24mm 广角透视、动态对角线构图、轻微鱼眼畸变、浅景深、高 ISO 胶片颗粒感、真实的肤色、清晰的织物纹理、头发和四肢的动态模糊，以及自发性的抓拍氛围。风格：{argument name=\"visual style\" default=\"照片级逼真的电影感编辑摄影\"}，暖色调阴影，高对比度，混乱而欢乐的氛围，无文字，无水印。","imgs":["https://r2.qqsrc.com/images/originals/17915.jpg"]},{"i":9974,"text":"创建一张逼真的、正面半身肖像照片，主角为一名 {argument name=\"profession\" default=\"女性护士或临床医生\"}，背景为一面纯色灰白色纹理墙。主体穿着 {argument name=\"scrub color\" default=\"酒红色\"} V 领医疗刷手服，短袖，观察者右侧有一个小胸袋，领口附近有金属按扣细节。一条精致的听诊器自然地挂在脖子上，黑色管路，银色金属耳挂，灰色耳塞靠近口袋，圆形的听诊头位于观察者左侧。人物留着中等长度的棕色头发，向后扎起，耳边有几缕碎发，姿态中立挺拔，双肩平齐，构图居中，裁剪范围从头顶上方到躯干中部。面部被一个大的方形肤色隐私马赛克块有意遮挡，隐藏了所有面部特征，同时保留了头发、耳朵、颈部、服装和听诊器。使用柔和均匀的室内光线，呈现清晰的摄影细节、自然的色彩、极简的背景，以及干净的临床证件照风格。","imgs":["https://r2.qqsrc.com/images/originals/17916.jpg"]},{"i":9975,"text":"以 REFERENCE_0 作为构图参考，REFERENCE_1 作为精细姿势/布局参考，将草图转化为精美的全彩动漫漫画分镜。保持相同的 4 人排列和姿势：中间后方 1 名强壮的学生正在展示肌肉，右侧 1 名金发学生正在展示肌肉，左侧 1 名白发小个子学生呈蹲姿蓄力，左下角前景 1 名红发角色被大面积截取并表现出震惊的表情。将粗糙的结构线替换为干净的墨线、赛璐珞阴影以及完整的校服配色。添加参考图中没有的高能漫画背景：密集的蓝色放射状速度线、网点纹理、蓝黄色星形图案以及黄色漫画爆炸特效。在右下角保留 1 个锯齿状对话框，其中包含垂直排列的日语文本 {argument name=\"speech bubble text\" default=\"なにしてんの?\"}。使最终图像呈现出戏剧性的喜剧少年漫画跨页分镜效果，具备清晰的轮廓、饱和的色彩和动态的视觉冲击力。","imgs":["https://r2.qqsrc.com/images/originals/17917.png"]},{"i":9976,"text":"{\"type\":\"简洁的日本角色指南海报 / 吉祥物样式表\",\"format\":\"横向 A4 海报，白色背景，细黑色分割线，编辑排版\",\"headline\":\"CHARACTER GUIDE\",\"subtitle\":\"{argument name=\\\"subtitle text\\\" default=\\\"『気づいたら、街が本でできてたんです。』のキャラクター紹介\\\"}\",\"visual_style\":\"极简扁平矢量插画，简洁的深蓝色轮廓，白色圆脸，圆点眼睛，细微的表情动作，充足的留白，友好的书镇旅游品牌风格，黄色、青色、橙色和深蓝色的点缀色\",\"layout\":{\"top_header\":\"左上角为大号加粗黑色英文标题，同一行配有日文副标题，下方有细水平线\",\"sections\":[{\"number\":\"01\",\"title\":\"棒人间角色\",\"position\":\"上部三分之二，全宽网格\",\"count\":24,\"description\":\"二十四个简单的火柴人吉祥物姿势，每个图形下方带有小的日文标签\",\"labels\":[\"歩く人\",\"読む人\",\"座る人\",\"窓からのぞく人\",\"階段をのぼる人\",\"会話する人\",\"親子\",\"集まる人\",\"くつろぐ人\",\"働く人\",\"本を運ぶ人\",\"本を選ぶ人\",\"自転車の人\",\"スマホを見る人\",\"本を持つ人\",\"犬と散歩する人\",\"なわとびする人\",\"スキーをする人\",\"屋上の人\",\"壁を塗る人\",\"ドアに入る人\",\"本を運ぶ人（積み上げ）\",\"植物を持つ人\",\"旅する人\"],\"pose_details\":\"包括以下动作：背着黄色手提袋走路、阅读黄色书籍、盘腿坐着看书、从窗户探出头并带有花朵、爬楼梯、两人交谈、亲子、三人聚在一起看书、在蓝色懒人沙发上放松、在摆放盆栽的桌前工作、推着装书的手推车、从书架选书、骑着装有黄色书箱的自行车、看智能手机、拿着书和蓝色小包、遛着深蓝色猫型狗、跳绳、戴着橙色帽子滑雪、坐在屋顶旁边有一只黑猫、用橙色油漆刷墙、进入蓝色门、搬运高高的一摞书、拿着盆栽，以及拉着绿松石色的行李箱\"},{\"number\":\"02\",\"title\":\"猫角色\",\"position\":\"左下角\",\"count\":4,\"description\":\"四个深蓝色猫吉祥物姿势\",\"labels\":[\"歩く\",\"立ち止まる\",\"のびる\",\"座る\"]},{\"number\":\"03\",\"title\":\"幽灵角色\",\"position\":\"底部中左侧\",\"count\":4,\"description\":\"四个白色幽灵吉祥物姿势，柔软圆润的床单状身体，圆点眼睛\",\"labels\":[\"すわる\",\"たたずむ\",\"よこむき\",\"のぞく\"]},{\"number\":\"04\",\"title\":\"角色特征\",\"position\":\"底部中右侧\",\"count\":6,\"description\":\"六个特征标注，配有小图标或色块\",\"labels\":[\"シンプルな線\",\"小さな表情\",\"白い顔\",\"紺の線画\",\"アクセントカラーの小物\",\"生活感のあるポーズ\",\"親しみやすい余白\"]},{\"number\":\"05\",\"title\":\"使用场景示例\",\"position\":\"右下角\",\"count\":6,\"description\":\"六个应用示例，以海报、社交媒体帖子、网站、标识、商店工具和图标的小型样机形式展示\",\"labels\":[\"ポスター\",\"SNS投稿\",\"ウェブサイト\",\"サイン・案内\",\"ショップツール\",\"アイコン\"]}]},\"typography\":\"CHARACTER GUIDE 使用加粗压缩无衬线字体，章节标题和标签使用简洁的日文黑体，黑色文本，章节编号 01 至 05\",\"color_palette\":{\"line\":\"深蓝色\",\"faces\":\"白色\",\"main accents\":\"{argument name=\\\"accent colors\\\" default=\\\"yellow, teal, orange, dark navy\\\"}\",\"background\":\"白色\",\"divider_lines\":\"黑色或灰色\"},\"character_system\":{\"human\":\"{argument name=\\\"human character style\\\" default=\\\"圆白头，深蓝色发帽或简单的深蓝色轮廓，细火柴棍四肢，小圆点眼睛，无嘴，极简服装\\\"}\",\"cat\":\"深蓝色简约猫，明亮的眼睛，长尾巴，顽皮的姿势\",\"ghost\":\"白色圆润幽灵，深蓝色轮廓，小圆点眼睛，温和可爱的氛围\"},\"composition_instructions\":\"制作一张精致的单页指南，使其看起来像书镇活动的内部提案海报。保持插图较小、间距均匀且标注清晰。使用细垂直分割线分隔底部的四个部分。确保所有 24 个火柴人姿势、4 个猫姿势、4 个幽灵姿势、6 个特征标注和 6 个使用样机清晰可见且可数。保留指定的日文章节标题和标签。\",\"quality\":\"清晰的矢量线条，适合打印，边距平衡，无照片级真实感，无渐变，无复杂阴影\"}","imgs":["https://r2.qqsrc.com/images/originals/17918.jpg"]},{"i":9977,"text":"{\n  \"type\": \"日语火箭工程信息图\",\n  \"format\": \"单张正方形教育信息图，1:1 长宽比\",\n  \"theme\": \"基于基础火箭工程学，解释火箭任务中最困难的部分是从地表抵达近地轨道\",\n  \"language\": \"日语\",\n  \"visual style\": \"深海军蓝太空科技风信息图，配以亮蓝色章节标题、黄橙色高亮、白色日语字体、简洁的工程图解、逼真的 3D 火箭与行星渲染，高对比度，精致的社交媒体科普设计\",\n  \"headline\": \"{argument name=\\\"headline text\\\" default=\\\"火箭发射最难的一步：从地表到近地轨道（LEO）\\\"}\",\n  \"subtitle\": \"{argument name=\\\"subtitle text\\\" default=\\\"只要能抵达那里，任务就相当于成功了一半\\\"}\",\n  \"canvas\": {\n    \"background\": \"深海军蓝渐变，带有细微的网格线和太空氛围光晕\",\n    \"border\": \"整张信息图周围有细蓝色边框\",\n    \"layout\": \"顶部标题，上方两个大面板并排，中间一个宽成本面板，底部一个总结横幅\"\n  },\n  \"layout\": {\n    \"sections count\": 5,\n    \"sections\": [\n      {\n        \"title\": \"大部分 Δv 消耗在从地表到近地轨道（LEO）的过程中\",\n        \"position\": \"左上\",\n        \"content type\": \"垂直高度与 delta-v 对比图表，配火箭发射插图\",\n        \"main visual\": \"最左侧为大型黑白重型火箭升空，带有明亮的橙色火焰和烟云\",\n        \"chart columns\": [\"到达高度（参考）\", \"所需 Δv（参考）\"],\n        \"altitude stages count\": 4,\n        \"altitude stages\": [\n          {\"label\": \"近地轨道（LEO）\", \"altitude\": \"200〜2,000 km\", \"delta v\": \"约 9,000〜9,500 m/s（总量的约 85〜90%）\", \"icon\": \"小型卫星\"},\n          {\"label\": \"脱离大气层\", \"altitude\": \"100 km 以上\", \"delta v\": \"约 1,200 m/s（约 10%）\", \"icon\": \"小型倾斜火箭\"},\n          {\"label\": \"高空（大气阻力小）\", \"altitude\": \"10〜20 km\", \"delta v\": \"约 300〜400 m/s（约 3〜4%）\", \"icon\": \"小型火箭\"},\n          {\"label\": \"上升（重力与空气阻力）\", \"altitude\": \"地表〜10 km\", \"delta v\": \"约 1,500〜2,000 m/s（约 15〜20%）\", \"icon\": \"小型火箭机头向上\"}\n        ],\n        \"callouts count\": 2,\n        \"callouts\": [\n          {\"text\": \"抵达 LEO 所需的 Δv 极其巨大！\", \"style\": \"深色边框内的黄色标题\"},\n          {\"text\": \"只要能抵达 LEO，任务就相当于成功了一半\", \"style\": \"带有向下箭头的橙色大边框\"}\n        ]\n      },\n      {\n        \"title\": \"从 LEO 到月球轨道或火星轨道的 Δv 差值较小\",\n        \"position\": \"右上\",\n        \"content type\": \"太空轨道对比图与 delta-v 表格\",\n        \"celestial bodies count\": 3,\n        \"celestial bodies\": [\n          {\"label\": \"LEO\", \"description\": \"带有蓝色大气的地球，虚线圆形轨道，标注 200〜2,000 km\"},\n          {\"label\": \"月球轨道（Lunar Orbit）\", \"description\": \"虚线轨道上的灰色月球，标注约 1,000〜2,000 km 高度\"},\n          {\"label\": \"火星轨道（Mars Orbit）\", \"description\": \"虚线轨道上的橙色火星，标注约 300〜1,000 km 高度\"}\n        ],\n        \"trajectory arrows count\": 2,\n        \"trajectory arrows\": [\"地球/LEO 到月球\", \"月球到火星\"],\n        \"comparison boxes count\": 2,\n        \"comparison boxes\": [\n          {\"label\": \"LEO → 月球轨道\", \"value\": \"约 3,100 m/s\"},\n          {\"label\": \"LEO → 火星轨道\", \"value\": \"约 4,900 m/s\"}\n        ],\n        \"highlight\": \"差值仅约 1,800 m/s\",\n        \"definition box\": {\n          \"title\": \"什么是 Δv（Delta-v）？\",\n          \"text\": \"指改变火箭或航天器速度所需的总速度量。数值越大，所需的燃料就越多。\",\n          \"icon\": \"灯泡\"\n        },\n        \"reference list count\": 4,\n        \"reference list\": [\n          \"地表 → LEO（近地轨道）: 约 9,000〜9,500 m/s\",\n          \"LEO → 月球轨道: 约 3,100 m/s\",\n          \"LEO → 火星轨道: 约 4,900 m/s\",\n          \"LEO → 地球静止轨道（GEO）: 约 3,900 m/s\"\n        ],\n        \"footnote\": \"※数值会因燃油效率和条件而异。\"\n      },\n      {\n        \"title\": \"昂贵火箭的现实：大部分成本也集中在“抵达 LEO”\",\n        \"position\": \"中间全宽\",\n        \"content type\": \"成本构成面板\",\n        \"subcomponents count\": 4,\n        \"subcomponents\": [\n          {\"type\": \"环形图\", \"label\": \"80〜90%\", \"secondary label\": \"10〜20%\", \"colors\": \"黄色和蓝色\"},\n          {\"type\": \"图例\", \"items count\": 2, \"items\": [\"地表→LEO 成本（发射、燃料、机体结构、研发费等）\", \"LEO 以外的任务成本（轨道变更、航行、观测仪器等）\"]},\n          {\"type\": \"硬币堆叠插图\", \"label\": \"火箭发射费用参考（单次）\", \"value\": \"数十亿至数百亿日元以上\"},\n          {\"type\": \"小型火箭发射图标与说明文字\", \"text\": \"在一次性火箭中，大部分燃料和机体结构都在抵达 LEO 的过程中被消耗或丢弃。换句话说，运送到 LEO 是最昂贵的部分。\"}\n        ]\n      },\n      {\n        \"title\": \"总结：从地表到 LEO 是最大的壁垒。跨越它，宇宙将变得触手可及。\",\n        \"position\": \"底部全宽\",\n        \"content type\": \"总结横幅\",\n        \"icon\": \"左侧圆圈内的大型黄色勾选标记\",\n        \"background visual\": \"弯曲的地平线和右侧的小型火箭发射\",\n        \"body text\": \"理解火箭工程的现实，就能看清太空任务的难度与成本结构。\"\n      },\n      {\n        \"title\": \"整体视觉装饰\",\n        \"position\": \"贯穿全图\",\n        \"content type\": \"装饰性技术元素\",\n        \"items count\": 5,\n        \"items\": [\"蓝色面板标题\", \"橙色箭头\", \"细分割线\", \"小型航天器图标\", \"发光的黄色强调文字\"]\n      }\n    ]\n  },\n  \"typography\": {\n    \"headline\": \"大型加粗白色日语无衬线字体，包含 LEO 短语\",\n    \"subtitle\": \"加粗黄色日语无衬线字体\",\n    \"body\": \"紧凑简洁的白色日语文本\",\n    \"numbers\": \"用于 delta-v 数值的大号加粗白色和黄色数字\"\n  },\n  \"color palette\": {\n    \"primary background\": \"{argument name=\\\"background color\\\" default=\\\"深海军蓝\\\"}\",\n    \"accent\": \"{argument name=\\\"accent color\\\" default=\\\"金黄橙色\\\"}\",\n    \"secondary\": \"电光蓝\",\n    \"text\": \"白色\"\n  },\n  \"rendering instructions\": \"制作一张清晰、信息密度高、适合 X/Twitter 的日语信息图。保持所有标签锐利易读，面板对齐整洁，保留指定的日语文本，将逼真的火箭/行星插图与扁平化 UI 风格图表相结合，并避免结构化面板之外的杂乱内容。\"\n}","imgs":["https://r2.qqsrc.com/images/originals/17919.jpg"]},{"i":9978,"text":"{\"type\":\"日式插画城市海报\",\"format\":\"竖版 A1 尺寸宣传海报\",\"theme\":\"以书构成的神保町小镇、书店、阅读文化、趣味城市探索\",\"headline\":\"{argument name=\\\"headline text\\\" default=\\\"気づいたら、街が本でできてたんです\\\"}\",\"main_visual\":{\"description\":\"一幅内容密集的等轴测插画，描绘了一个充满活力的书香街区，建筑、人行道、屋顶、广场和道路都与超大号的书籍和书页融为一体。主体建筑是一个温暖的橙色书店风格街区，配有青色窗户、黄色点缀、蓝色饰边、外部阳台，窗边有人在阅读，还有漂浮在空中或嵌入建筑结构中的翻开的书籍。周围的建筑包括一个黄色屋顶阅读露台、一个弯曲的蓝黄相间图书馆外墙、一个构成广场的巨大闭合书籍、作为建筑楼板的书堆，以及形状像书页边缘的楼梯。\",\"style\":\"扁平矢量编辑插画，日式海报设计，干净的黑色轮廓，有限的专色调色板，趣味建筑剖面，大量微小的人物活动，清晰的印刷质感，非写实风格\",\"palette\":\"{argument name=\\\"color palette\\\" default=\\\"橙色、青蓝色、芥末黄、奶油白、黑色和暖灰色\\\"}\",\"perspective\":\"高角度等轴测城市透视图，无地平线\",\"mood\":\"好奇、文学气息、生动、奇幻、以社区为中心\"},\"layout\":{\"poster_orientation\":\"纵向\",\"top_area\":\"顶部为醒目的大号黑色日文标题，与下方插画中的书屋屋顶略有重叠。\",\"centerpiece\":\"一幅连续的城市插画占据海报大部分区域，周围留有白色边距和垂直侧边文字栏。\",\"bottom_area\":\"下边缘有一段简短的日文说明文字，右下角为制作方信息和 Logo。\",\"text_columns\":{\"count\":6,\"labels\":[\"左上垂直引文：关于新旧书店共存\",\"左中垂直引文：关于年轻人与多元世代\",\"左下垂直引文：关于免费刊物与日常书店探访\",\"右上垂直引文：关于作为设计与建筑灵感的书之城\",\"右中垂直引文：关于像挖掘书店街一样寻找旧书\",\"右下垂直引文：关于一个人在旧书街通勤 20 年的感悟\"]}},\"visible_text\":{\"headline\":\"気づいたら、街が本でできてたんです\",\"large_logo\":\"JIN BO CHO\",\"bottom_explanation\":\"“気づいたら（回过神来）”一词，蕴含了街区居民无意识的情感。在神保町，书并非特殊存在，而是自然地融入了街区风景。文化在不知不觉中扎根，日常生活中拥有“书”已成为理所当然，这段文字正是为了表达这种神保町特有的氛围。然而，当你真正走在街上时，会发现咖喱的香气、乐器的声音、冬季运动用品店，以及从古书剧场传出的笑声交织在一起。那些无法仅用书来概括、充满活力的多元文化，正是“回过神来已成为书之街”的神保町当下的象征。\",\"credit\":\"Produced by TAM\",\"logo\":\"TAM\"},\"enumerated_scene_elements\":{\"tiny_people_count\":\"约 54 个简化的白色火柴人角色，散布在窗户、屋顶、街道、楼梯、广场和阳台上\",\"major_book_elements_count\":13,\"major_book_elements\":[\"构成左上屋顶的巨大翻开书籍\",\"横跨顶部中心的超大书页堆\",\"左下方橙色建筑附近漂浮的翻开书籍\",\"构成中央广场的巨大闭合青色书籍\",\"中央广场上的三本书堆\",\"黄色屋顶露台上的翻开书籍\",\"最右侧巨大的垂直书页墙\",\"左下深色建筑上的书形屋顶\",\"右侧街道上平放的蓝色书籍\",\"右侧边缘由大人物持有的翻开书籍\",\"中央黄色平台上散落的小书和纸张\",\"嵌入弯曲蓝色外墙的书架\",\"构成路径和楼梯状建筑边缘的书堆\"],\"activity_groups_count\":12,\"activity_groups\":[\"在上方橙色建筑窗边阅读的人们\",\"沿着左侧外墙攀爬绳索的人\",\"在黄色屋顶露台上坐着阅读的人\",\"在弯曲蓝色外墙内浏览书架的人\",\"在中央广场边缘交谈的两人\",\"在黄色平台上坐在散落纸张间阅读的群体\",\"在建筑间狭窄街道行走的人们\",\"在左中街道骑自行车的人\",\"右下角坐在橙色椅子上的小型观众\",\"右侧边缘持有翻开书籍的大型局部人物\",\"左侧屋顶露台上的幽灵般白色角色\",\"右上天空区域的小型奇幻飞碟与生物\"]},\"characters\":{\"design\":\"极简圆头人形，白色身体，海军蓝头发或帽子，简单的圆点眼睛，细长的四肢，偶尔带有包、书、乐器或阅读道具。\",\"clothing\":\"大多为简单的白色服装配海军蓝点缀；少数角色带有橙色、青色或黄色配饰。\"},\"typography\":{\"headline_style\":\"超大加粗黑色日文哥特体，手工排版，具有强烈的比例对比\",\"side_text_style\":\"窄版垂直日文文字栏，带有小号年龄/性别标签\",\"logo_style\":\"右下角醒目的黑色堆叠拉丁字母 JIN BO CHO\"},\"composition_rules\":\"保持插画内容丰富但清晰易读，每个小场景都通过楼梯、道路、窗户、书架、阳台和书页状建筑连接。使用强烈的几何形状、干净的矢量边缘和宽敞的白色海报边距。确保标题依然是最强的视觉元素，街区占据中心位置，侧边引文作为编辑海报文案阅读。\",\"customization\":{\"location\":\"{argument name=\\\"location name\\\" default=\\\"神保町\\\"}\",\"poster credit\":\"{argument name=\\\"poster credit\\\" default=\\\"Produced by TAM\\\"}\",\"main logo text\":\"{argument name=\\\"main logo text\\\" default=\\\"JIN BO CHO\\\"}\"}}","imgs":["https://r2.qqsrc.com/images/originals/17920.jpg"]},{"i":9979,"text":"{\"type\":\"日式角色介绍 / 吉祥物风格指南海报\",\"canvas\":\"横向 4:3 海报，采用暖色调米白色纸张，干净的编辑排版，带有细深蓝色边框的圆角矩形面板，扁平矢量插画，极简可爱吉祥物设计，深蓝色排版与线条艺术，黄色色块点缀\",\"title\":{\"text\":\"{argument name=\\\"main title\\\" default=\\\"おばけキャラクター紹介\\\"}\",\"position\":\"左上\",\"style\":\"大号粗体深蓝色日式无衬线字体\"},\"subtitle\":{\"text\":\"{argument name=\\\"subtitle text\\\" default=\\\"『気づいたら、街が本でできてたんです。』より\\\"}\",\"position\":\"标题下方\",\"style\":\"较小的深蓝色日文文本\"},\"character\":{\"name\":\"{argument name=\\\"character name\\\" default=\\\"小型幽灵吉祥物\\\"}\",\"appearance\":\"简单的白布状幽灵，圆顶头部，柔软的波浪形下摆，微小的椭圆形深蓝色眼睛，无嘴，柔和友好的轮廓，根据姿势配有悬垂的小腿或脚\",\"line_style\":\"粗而平滑的深蓝色轮廓，极简的内部褶皱\",\"personality\":\"温和、好奇、略带羞涩、热爱书籍的街区精灵\"},\"layout\":{\"sections\":[{\"title\":\"メインビジュアル\",\"position\":\"左中\",\"count\":1,\"content\":\"大型主幽灵坐着阅读，两只小椭圆眼，白色身体配深蓝色轮廓，双脚置于前方，布料下摆有细微褶皱\",\"label_style\":\"带白色日文文本的小型深蓝色胶囊标签\"},{\"title\":\"参考ビジュアル\",\"position\":\"右上\",\"count\":1,\"content\":\"带框参考插画，展示幽灵沿着明亮的黄色街道或书架般的路径行走或坐着，同时拿着并阅读一本蓝色书籍；包含一盆植物和简化的建筑/书店细节\",\"frame\":\"深蓝色圆角矩形\"},{\"title\":\"基本ポーズ\",\"position\":\"右中\",\"count\":4,\"labels\":[\"すわって読む\",\"ただずむ\",\"のぞく\",\"のんびり歩く\"],\"content\":\"四个独立的幽灵吉祥物深蓝色线条画：1 坐着阅读，双脚伸出；2 站立，露出两只小脚；3 从垂直墙边探出；4 悠闲行走，露出小脚\"},{\"title\":\"キャラクターの特徴\",\"position\":\"左下\",\"count\":5,\"labels\":[\"白い布のような形\",\"小さな目\",\"やわらかい輪郭\",\"のんびりした存在\",\"街にひそむ小さな発見\"],\"content\":\"包含五个项目符号的日文特征列表\"},{\"title\":\"カラー\",\"position\":\"下中\",\"count\":3,\"labels\":[\"アウトライン ネイビー\",\"ボディ オフホワイト\",\"アクセント イエロー\"],\"content\":\"三个色卡：深蓝色、米白色、亮黄色\",\"colors\":{\"outline\":\"{argument name=\\\"outline color\\\" default=\\\"深蓝色\\\"}\",\"body\":\"{argument name=\\\"body color\\\" default=\\\"米白色\\\"}\",\"accent\":\"{argument name=\\\"accent color\\\" default=\\\"亮黄色\\\"}\"}},{\"title\":\"使い方イメージ\",\"position\":\"右下\",\"count\":2,\"labels\":[\"ポスターのアイコン例\",\"サイン・案内のアイコン例\"],\"content\":\"两个使用场景模拟：1 带坐姿幽灵和黄色下方的海报图标卡；2 指示/引导图标卡，展示幽灵从大黄色右箭头旁边的深蓝色垂直条中探出，带有圆角边框和黄色强调线\"}],\"overall_grid\":\"非对称信息表：左侧为大型主视觉插画，右侧为参考视觉和姿势研究，下方为三个信息面板\"},\"typography\":\"日式圆体无衬线字体，深蓝色，粗体章节标题，整洁的间距，具有设计文档的质感\",\"rendering\":\"扁平 2D 矢量艺术，线条清晰利落，除简单的色块外无阴影，专业的吉祥物提案表，高可读性\"}","imgs":["https://r2.qqsrc.com/images/originals/17921.jpg"]},{"i":9980,"text":"以 REFERENCE_0 作为基础景观，移除所有 YAMAP 品牌标识、日期、路线及数据叠加文本，将场景转换为精致的动漫风格旅行插画，同时保留俯瞰城市、湖泊、远山、朦胧天空和绿色森林前景的山顶视角。添加一名前景角色：一位年轻的动漫徒步者，背影/四分之三侧背影，站在古老的石制城堡墙头眺望风景。为角色设置 {argument name=\"hair color\" default=\"长长的水蓝色头发\"}，扎成高马尾，配有蓝色丝带和星星发饰，身穿浅蓝色徒步衬衫、米色工装徒步裤、棕色徒步靴，佩戴露指手套，背着一个大型深色徒步背包。在角色身上或附近添加 4 个清晰可见的装备/配饰元素：1 个绑在背包上的卷起睡垫、1 个悬挂的蓝色星星挂件、1 只停在肩膀附近的小型蓝色鸟类伙伴，以及 1 个小型徒步小包/肩带细节。在角色脚下添加风化的石块，并在下方前景处加入柔和模糊的绿叶以增加景深。保持构图优美宁静，呈现明亮的晨光、柔和的大气朦胧感、角色清晰的动漫线条，以及背景中柔和细腻的半写实风格。不要包含任何文本、Logo、UI 或水印。","imgs":["https://r2.qqsrc.com/images/originals/17922.jpg"]},{"i":9981,"text":"{\"type\":\"竖版双格漫画页\",\"style\":\"动态日式漫画插画，干净的墨线轮廓，柔和的水彩阴影，富有表现力的速度线和醒目的拟声词，优雅幻想与混乱现实之间的喜剧对比\",\"format\":\"长条形手机漫画页，两个堆叠的画格由粗黑线分隔\",\"characters\":{\"main woman\":{\"description\":\"年轻女性，拥有 {argument name=\\\"hair color\\\" default=\\\"淡蓝色齐肩发\\\"}，脸部刻意用方形马赛克遮挡，身材曲线优美，姿态充满活力\",\"panel 1 outfit\":\"优雅修身的白色旗袍，带有蓝色花卉刺绣，高开叉，深色滚边，黑色高跟鞋\",\"panel 2 outfit\":\"休闲粉色 T 恤，腰间系着绿色围裙或外套，黑色短裤，赤脚或穿着平底鞋，造型凌乱干练\"}},\"setting\":{\"panel 1\":\"明亮的高档港式点心餐厅，想象中精致宽敞，奶油色墙壁，吊灯或嵌入式天花板灯，铺着白色桌布的圆桌，餐椅，浅色抛光地板\",\"panel 2\":\"同一家餐厅，转变为拥挤混乱的点心餐桌场景，充满动感、蒸汽、背景剪影，圆木桌上散落着各种餐点\"},\"layout\":{\"panel count\":2,\"panels\":[{\"position\":\"上半部分\",\"scene\":\"幻想版本：女子以优雅的服务员姿势站立，面带微笑（暗示），双臂抬起平衡着两个装满竹蒸笼的托盘；一条腿向后弯曲，构图如同优雅的宣传漫画\",\"visible food count\":3,\"visible foods\":[\"左手托盘上的两个竹蒸笼\",\"右手托盘上的两个竹蒸笼\",\"前景桌上的一盘点心，放着两个蒸包，其中一个已打开露出肉馅\"],\"text elements count\":2,\"text elements\":[{\"type\":\"竖排标题框\",\"position\":\"右上角\",\"text\":\"{argument name=\\\"top caption text\\\" default=\\\"想象中的香港\\\"}\"},{\"type\":\"对话气泡\",\"position\":\"中右\",\"text\":\"{argument name=\\\"top speech text\\\" default=\\\"哇～肉包子来喽～\\\"}\"}]},{\"position\":\"下半部分\",\"scene\":\"现实版本：女子扑向凌乱的餐桌，一只手猛地放下或放置一盘白灼虾肠粉，另一只手拿着一笼华夫饼状或油炸点心；视角倾斜，动作感强烈\",\"visible food and tableware count\":9,\"visible foods and tableware\":[\"中央大白盘，装着虾肠粉\",\"左下角的竹蒸笼，装着三个包子或饺子\",\"左下角的白茶壶\",\"中左侧的小红调料罐\",\"中下侧的小茶杯\",\"右中侧的竹蒸笼，装着小虾饺\",\"前方白盘，放着吃剩的饺子和碎屑\",\"右下角的小碗和勺子\",\"右下角碗上斜放的一双筷子\"],\"text elements count\":8,\"text elements\":[{\"type\":\"竖排标题框\",\"position\":\"右上角\",\"text\":\"{argument name=\\\"right caption text\\\" default=\\\"我爱的香港\\\"}\"},{\"type\":\"锯齿状对话气泡\",\"position\":\"左侧\",\"text\":\"{argument name=\\\"bottom speech text\\\" default=\\\"鲜虾肠粉呀～!!\\\"}\"},{\"type\":\"拟声词\",\"position\":\"头部附近右上角\",\"text\":\"嘈杂!!\"},{\"type\":\"拟声词\",\"position\":\"上中\",\"text\":\"破碎!!\"},{\"type\":\"拟声词\",\"position\":\"中左\",\"text\":\"哐当\"},{\"type\":\"拟声词\",\"position\":\"中下\",\"text\":\"砰!!\"},{\"type\":\"手写小字\",\"position\":\"左下\",\"text\":\"唔该\"},{\"type\":\"手写小标记\",\"position\":\"背景中央\",\"text\":\"人\"}]}]},\"mood\":\"幽默对比浪漫化的港式点心与喧闹、生动、真实的香港餐厅混乱场景\",\"composition notes\":\"在两个画格中都保持脸部被方形灰色马赛克遮挡；强调上半格的精致与平静，下半格的嘈杂、杂乱与动感；使用带有粗黑边框和白色对话气泡的竖排日式漫画排版\"}","imgs":["https://r2.qqsrc.com/images/originals/17923.jpg"]},{"i":9982,"text":"创作一张优雅的深色维多利亚风格更衣室竖版手机壁纸，营造出为精致茶会做准备的氛围。在左上方用纤细的白色日文明朝体书写 {argument name=\"quote\" default=\"整えた心で、君を待つ。\"}，并在文字下方添加一个小巧的装饰性分割线。画面中有一把雕花椅子，上面搭着一件黑白配色的女仆风格服饰：黑色中片、白色围裙式前襟、宽大的白色荷叶边，以及胸前饰有金质胸针和垂坠链条流苏的巨大黑色蝴蝶结。前景放置一个抛光的银色托盘，上面精确摆放四件茶具：一个带有金色装饰的白瓷茶壶、一个配套的糖罐、一个盛有琥珀色茶水的茶杯及杯托，以及一个带有圆顶的小金钟或盖碗，旁边放着一把精致的勺子。右侧放置一件折叠好的白色蕾丝边女仆配饰或围裙，带有黑色肩带和金质奖章。梳妆台上精确摆放五件梳妆物品：一盏带有奶油色灯罩的暖光台灯、一面金框大椭圆镜、一个插有薰衣草的花瓶、一个带有两个紫色丝带蝴蝶结的蕾丝发带，以及三个圆形小金盒。添加两处花艺布置：玻璃花瓶中的薰衣草，以及右下角黑色小花瓶中类似紫色藏红花的鲜花，桌面上散落着几片紫色花瓣。使用 {argument name=\"room style\" default=\"深色古董红木维多利亚室内风格\"}，运用温暖的灯光，左侧高窗透入柔和的日光并配有深色窗帘，展现丰富的雕花木板、反光的金属表面、深邃的阴影，营造浪漫的等候室氛围，色调采用黑、象牙白、金、棕和紫色的柔和配色。构图采用竖屏 9:16 比例，椅子位于左侧，梳妆台和镜子位于右侧，茶盘位于前景下方，并在短句周围留出充足的深色负空间。","imgs":["https://r2.qqsrc.com/images/originals/17924.jpg"]},{"i":9983,"text":"创作一张竖屏手机壁纸风格的奇幻背景插画，场景设定在黄金时刻一座富丽堂皇的宫殿房间内。透过带有华丽黑金格栅的高大拱窗，可以看到远处模糊的圆顶宫殿和尖塔。左侧拉开一扇深红色的花纹窗帘，顶部中央悬挂着一个流苏。前景中，放置一张深色雕花木桌，桌上摆满了奢华的道具：一个带有红色火漆印的白色信封、一叠散落的信件和纸张、一个黑色墨水瓶、一支竖立的黑色羽毛笔、一卷羊皮纸、一个华丽的黑金假面舞会面具、半杯红酒、一个装有燃烛的镂空金属灯笼，以及两块分别呈红色和黑金色的刺绣布料。运用温暖的琥珀色阳光、戏剧性的阴影、浮动的尘埃，营造出浪漫而神秘的氛围，色调以浓郁的酒红色、青铜色、黑色和金色为主。在左侧窗帘区域添加优雅的日语寄语文字 {argument name=\"message text\" default=\"仮面の奥に、\\n真実を隠して。\"}，采用精致的衬线字体，颜色为淡金色，下方配有一条纤细的水平金线和微小的闪光点。构图需具有电影感、宁静且略带忧郁，仿佛在暗示宫廷阴谋以及面具背后隐藏的真相。","imgs":["https://r2.qqsrc.com/images/originals/17925.jpg"]},{"i":9984,"text":"创作一张深色浪漫哥特风格的垂直奇幻背景插画，视角设在夜晚的高处石质阳台上。场景俯瞰着一座广阔且灯火通明的城堡城市，云层密布的深蓝色天空下，尖塔林立，窗户透出温暖的灯光，一轮满月高悬。左侧前景放置两根缠绕着常春藤和藤蔓的巨大风化石柱，一把椅子或栏杆上披着一件黑色斗篷或披风，木箱上放着一盏发光的黄铜灯。在下方前景处，摆放一张铺在深色木桌上的陈旧羊皮地图，一把饰有祖母绿的华丽匕首斜放在地图上，旁边是一只黑色皮手套、两卷用绳子系着的卷轴、阳台边缘附近的一个小金属杯或墨水瓶，右侧是一个装饰性的锁闭宝箱，以及一盆开着白色花朵的盆栽。前景使用温暖的烛光与远方城市清冷的月光形成对比，营造出一种静谧的守护氛围。在左侧石柱上添加一段优雅的白色衬线书法垂直日文短句，排版为两列垂直文本，内容为 {argument name=\"message text\" default=\"静かな刃は、君を守る。\"}。场景设定为 {argument name=\"setting mood\" default=\"一位沉默的守护者俯瞰王都\"}，以 {argument name=\"main foreground item\" default=\"一把镶嵌祖母绿的匕首\"} 作为视觉焦点，背景为 {argument name=\"sky condition\" default=\"月光下的云层\"} 和 {argument name=\"city style\" default=\"哥特奇幻城堡城市\"}。画面中不出现任何人物。","imgs":["https://r2.qqsrc.com/images/originals/17926.jpg"]},{"i":9985,"text":"{\"type\":\"日本信息图海报\",\"format\":\"方形垂直社交媒体图片\",\"language\":\"日语\",\"headline\":\"{argument name=\\\"headline text\\\" default=\\\"电动空中出租车的到来与缓解交通拥堵的期待\\\"}\",\"style\":\"简洁的扁平化矢量信息图，带有圆角矩形面板、蓝灰色轮廓、简约图标、浅灰色背景、加粗的日文无衬线字体、带编号的蓝色圆圈、说明性箭头、极简阴影\",\"layout\":{\"overall\":\"左侧三个大型堆叠说明面板，右侧两个优势标注卡片及一个问题标注卡片，全部整齐排列在网格中\",\"main_sections_count\":3,\"main_sections\":[{\"number\":\"1\",\"title\":\"曼哈顿⇔机场 7 分钟\",\"position\":\"左上宽面板\",\"visuals\":\"左侧为曼哈顿天际线及世界贸易中心一号大楼，中央为未来感电动空中出租车，右侧为肯尼迪国际机场 (JFK) 控制塔和航站楼，中间有虚线蓝色飞行弧线，圆形徽章标注 7 分钟，带有“曼哈顿”和“JFK 机场”小标签\"},{\"number\":\"2\",\"title\":\"电动出租车・时速约 320km\",\"position\":\"左中宽面板\",\"visuals\":\"大型黑白 eVTOL 空中出租车及旋翼，上方有较小的飞行器轮廓，绿色电池图标标注“电动电池”，速度表弧线标注“时速约 320km”，向下箭头指向第 3 部分\"},{\"number\":\"3\",\"title\":\"缓解拥堵期待\",\"position\":\"左下宽面板\",\"visuals\":\"两个并排的道路对比插图：左侧标注“拥堵（现状）”，显示城市街道上密集的车辆和黄色出租车；右侧标注“缓解拥堵（期待）”，显示车辆较少且道路通畅；一个独立的小方框标注“噪音降低”，配有静音扬声器图标及文字“需要提升静音技术”\"}],\"right_callouts_count\":3,\"right_callouts\":[{\"title\":\"电动出租车\",\"position\":\"右上蓝色边框卡片\",\"icon\":\"带有白色飞行出租车剪影的蓝色圆圈\",\"text\":\"环保的下一代交通工具\"},{\"title\":\"垂直起降\",\"position\":\"右中绿色边框卡片\",\"icon\":\"圆圈内的绿色向上箭头\",\"visuals\":\"小型空中出租车降落在灰色天际线上方的圆形屋顶停机坪上\",\"text\":\"从直升机停机坪垂直起降\"},{\"title\":\"缓解拥堵\",\"position\":\"右下橙色边框卡片上半部分\",\"icon\":\"橙色扬声器/公告图标\",\"text\":\"通过空中交通大幅减少地面拥堵\"}],\"issue_callouts_count\":1,\"issue_callouts\":[{\"title\":\"噪音挑战\",\"position\":\"右下橙色边框卡片下半部分\",\"icon\":\"橙色扬声器/公告图标\",\"text\":\"需要解决安全性和噪音等问题\"}]},\"subject_details\":{\"vehicle\":\"{argument name=\\\"vehicle type\\\" default=\\\"未来感电动空中出租车 eVTOL\\\"}\",\"route\":\"{argument name=\\\"route\\\" default=\\\"曼哈顿至肯尼迪国际机场\\\"}\",\"travel_time\":\"{argument name=\\\"travel time label\\\" default=\\\"7 分钟\\\"}\",\"top_speed\":\"{argument name=\\\"speed label\\\" default=\\\"时速约 320km\\\"}\"},\"design_constraints\":\"确保所有日文文本清晰易读，保留精确的面板编号 1、2、3，使用带有细蓝灰色边框的白色卡片，强调航空图标和交通对比，采用专业的说明性图形记录风格\"}","imgs":["https://r2.qqsrc.com/images/originals/17927.jpg"]},{"i":9986,"text":"{\"type\":\"日本公共安全信息图海报\",\"topic\":\"登山登记与安全预防措施\",\"headline\":\"{argument name=\\\"headline text\\\" default=\\\"饭能市登山届提交呼吁与山岳安全注意事项\\\"}\",\"style\":\"友好且具插画风格的政府公告，简洁的矢量艺术，粗圆边框，蓝色步骤编号，绿色山脉，温暖的米白色背景，手绘图形记录风格，清晰易读的日语文本，正方形社交媒体图片\",\"layout\":{\"overall\":\"正方形海报，顶部有醒目的大标题，中心为四格流程图，右下角有一个醒目的红色行动呼吁框，底部为浅绿色检查清单条\",\"main panels\":{\"count\":4,\"items\":[{\"number\":\"1\",\"position\":\"左上\",\"content\":\"警察、登山者和登山俱乐部代表图标，讨论安全问题；标签块显示“埼玉県警察”和“越生会”；中心文字为“去年黄金周埼玉县内发生 3 起遇险事故”\"},{\"number\":\"2\",\"position\":\"左下\",\"content\":\"山路插图，配有雪花和温度计图标；标签显示“棒之峰”、“雪与气温”，以及红色警告框“今年已有 4 人死亡”\"},{\"number\":\"3\",\"position\":\"中心\",\"content\":\"一份标题为“登山届”的文件，上方为警察与登山者交谈；主要标题为“促进提交登山届”\"},{\"number\":\"4\",\"position\":\"右上\",\"content\":\"剪贴板检查清单，旁边是戴帽子和穿着绿色装备的背包客；清单文字包括“目的地”、“成员”、“日程与时间”、“装备”、“联系方式等”；黄色信息框显示“有助于早期发现与救援！安全登山！”\"}]},\"flow arrows\":{\"count\":4,\"description\":\"蓝色箭头将面板 1 连接至面板 2，面板 1 连接至面板 3，面板 2 连接至面板 3，面板 3 连接至面板 4，展示安全意识的提升过程\"},\"call to action\":{\"position\":\"右下\",\"border\":\"粗红色圆角矩形\",\"icon\":\"红色检查清单纸和铅笔\",\"text\":\"{argument name=\\\"call to action text\\\" default=\\\"务必提交登山届，做好安全准备\\\"}\"},\"bottom checklist strip\":{\"count\":5,\"items\":[{\"icon\":\"带有定位针的地图\",\"label\":\"制定计划\"},{\"icon\":\"背包和装备\",\"label\":\"准备装备\"},{\"icon\":\"太阳、云、雨和温度计\",\"label\":\"确认天气与气温\"},{\"icon\":\"智能手机联系图标\",\"label\":\"确保联系方式\"},{\"icon\":\"向导或警察指示图标\",\"label\":\"量力而行！\"}]}},\"visual details\":{\"color palette\":\"绿色、海军蓝、红色警告强调色、浅黄色、奶油色背景\",\"typography\":\"粗体日语无衬线标题，死亡人数和行动文字使用红色强调，圆角框内的小标签\",\"mood\":\"紧迫但亲切，教育性，市政防灾公告\",\"subject location\":\"{argument name=\\\"city name\\\" default=\\\"饭能市\\\"}\",\"safety statistic\":\"{argument name=\\\"death toll text\\\" default=\\\"今年 4 人死亡\\\"}\",\"holiday statistic\":\"{argument name=\\\"incident statistic text\\\" default=\\\"去年黄金周埼玉县内发生 3 起遇险事故\\\"}\"},\"rendering instructions\":\"生成一张精美、清晰的日语信息图，所有文字拼写准确，间距平衡，图标风格统一，非写实风格，无多余面板，并严格保持面板数量和检查清单项数。\"}","imgs":["https://r2.qqsrc.com/images/originals/17929.jpg"]},{"i":9987,"text":"{\"type\":\"展示三个 AI 图像生成结果面板的宽幅社交媒体说明拼贴图\",\"canvas\":\"超宽水平白色背景，简洁的截图式构图，三个从左到右均匀分布的垂直智能手机结果模型\",\"overall_style\":\"移动端 UI 截图的写实合成，清晰的日语文字，圆角黑色 Prompt 框位于圆角图像网格上方，极简白色边距，看起来像是一张关于不同流派 Prompt 解读的日本科技推文示例图\",\"layout\":{\"panel_count\":3,\"panels\":[{\"position\":\"left\",\"theme\":\"法国文艺复兴时期农夫视角解读\",\"top_prompt_box\":{\"shape\":\"黑色圆角矩形，下方居中有一个小向下箭头\",\"text\":\"{argument name=\\\"左侧 Prompt 文本\\\" default=\\\"请生成一张图像，精准再现一位对现代一无所知的法国文艺复兴时期农夫在收到以下 Prompt 时，脑海中自由构思出的 15 秒影像的 25 个印象深刻的切片。该影像的本质并非特效堆砌，而是由一位杰出艺术家创作的……\\\"}\"},\"grid\":{\"position\":\"位于 Prompt 框下方\",\"shape\":\"大型圆角矩形手机相册\",\"count\":25,\"arrangement\":\"5 列 5 行\",\"thumbnail_labels\":\"左上角带有 1 到 25 的白色小数字\",\"contents\":\"25 张柔和的电影感中世纪或文艺复兴时期法国乡村分镜静帧：石屋、披风人物、田野、布帘、楼梯、拱门、剪影、尘土飞扬的室内、油画色彩、深褐色和橄榄色调\",\"ui_overlays\":[\"左下角圆角深色编辑按钮\",\"右下角分享/上传图标\"]}},{\"position\":\"center\",\"theme\":\"来自 Bon-Art 动画工作室的粗线条男女童动漫视角解读\",\"top_prompt_box\":{\"shape\":\"黑色圆角矩形，下方居中有一个小向下箭头\",\"text\":\"{argument name=\\\"中间 Prompt 文本\\\" default=\\\"请生成一张图像，精准再现一对生活在 Lo-fi 且略显寂寥的 Bon-Art 风格动画中、天真无邪的男女童在满天星斗下收到以下 Prompt 时，脑海中自由构思出的 15 秒影像的 25 个印象深刻的切片。该影像……\\\"}\"},\"grid\":{\"position\":\"位于 Prompt 框下方\",\"shape\":\"大型圆角矩形手机相册\",\"count\":25,\"arrangement\":\"5 列 5 行\",\"thumbnail_labels\":\"左上角带有 1 到 25 的白色小数字\",\"contents\":\"25 张深蓝色 Lo-fi 动漫分镜静帧：两个简单的儿童角色、星空、发光的萤火虫或漂浮的光点、月光下的水面、剪影、面部特写、手部、纸张或笔记本、安静的情感氛围\",\"ui_overlays\":[\"左下角圆角深色编辑按钮\",\"右下角分享/上传图标\"]}},{\"position\":\"right\",\"theme\":\"居住在濑户内海港口民宅的三只家猫视角解读\",\"top_prompt_box\":{\"shape\":\"黑色圆角矩形，下方居中有一个小向下箭头\",\"text\":\"{argument name=\\\"右侧 Prompt 文本\\\" default=\\\"请生成一张图像，精准再现一只生活在濑户内海港口老家的年迈三花猫在收到以下 Prompt 时，脑海中自由构思出的 15 秒影像的 25 个印象深刻的切片。该影像的本质并非特效堆砌，而是由一位杰出艺术家在次日午后……\\\"}\"},\"grid\":{\"position\":\"位于 Prompt 框下方\",\"shape\":\"大型圆角矩形手机相册\",\"count\":25,\"arrangement\":\"5 列 5 行\",\"thumbnail_labels\":\"左上角带有 1 到 25 的白色小数字\",\"contents\":\"25 张温暖的写实电影感猫咪与日本海边民宅分镜静帧：三花猫、港口景色、榻榻米房间、阳光照射的窗户、船只、瓦片街道、猫眼特写、鱼市或沿海小镇氛围、午后的金色光线\",\"ui_overlays\":[\"左下角圆角深色编辑按钮\",\"右下角分享/上传图标\"]}}]},\"typography\":\"黑色框内的日语无衬线白字，缩略图上的数字标签，移动端 UI 风格\",\"camera\":\"完整合成图的正射投影，无透视畸变\",\"quality\":\"高分辨率、清晰、易读、精致，但明显是截图拼贴\",\"avoid\":\"不要添加额外的面板，不要替换三个 5x5 的缩略图网格，避免在日语 Prompt 框内出现除编辑和分享图标 UI 标签外的英文\"}","imgs":["https://r2.qqsrc.com/images/originals/17930.jpg"]},{"i":9988,"text":"{\"type\":\"可爱的动漫教育类剖面插画海报\",\"format\":\"垂直 2:3 海报\",\"style\":\"高细节手绘动漫风，温暖的绘本光影，清晰的信息图标签，奇幻且写实的城市地质横截面\",\"scene\":{\"concept\":\"一只三花小猫在大阪新世界和通天阁正下方的深层地下舒适房间中醒来，展示从地面到地下约 -80 米的垂直剖面。\",\"location\":\"{argument name=\\\"location\\\" default=\\\"大阪新世界，通天阁正下方\\\"}\",\"surface_city\":\"明亮的蓝天和少量云朵，拥挤的复古大阪娱乐区，通天阁位于地面中心，上方有写着“通天阁”的大型垂直招牌，两侧是色彩缤纷的商店建筑和广告牌，左侧有一个巨大的河豚餐厅招牌，充满昭和时代的标志\",\"underground_room\":\"深处的岩石洞穴卧室，粗糙的石墙，裸露的管道，温暖的灯笼，小床和毯子，矮桌上的马克杯，黑板地图，储物箱，舒适的秘密基地氛围\"},\"main_subject\":{\"species\":\"{argument name=\\\"animal\\\" default=\\\"睡眼惺忪的三花小猫\\\"}\",\"appearance\":\"圆滚滚毛茸茸的小猫，带有橙色、白色和深灰色斑块，粉色的内耳，虎斑尾巴，一只眼睛眯着打哈欠，一只爪子揉着眼睛，另一只爪子放在毯子上，可见肉垫\",\"pose\":\"坐在被窝里，盖着桃粉色的毯子，刚睡醒的样子\",\"mood\":\"可爱、困倦、安全、幽默\"},\"layout\":{\"composition\":\"单张垂直海报，顶部三分之一为地表城市，中间为地下土层和深度刻度，底部为舒适的小猫洞穴；通天阁与虚线垂直中心线对齐，指向下方的小猫房间\",\"depth_scale\":{\"position\":\"左边缘\",\"count\":\"9 个标注深度标记\",\"labels\":[\"地表\", \"0m\", \"-10m\", \"-20m\", \"-30m\", \"-40m\", \"-50m\", \"-60m\", \"-70m\", \"-80m\"]},\"geological_layers\":{\"count\":4,\"labels\":[\"埋立层（砾石·砂·粘土）\", \"冲积层（砂·粉砂·粘土）\", \"洪积层（砂砾·粘土）\", \"大阪层群（砂岩·页岩·砾岩）\"],\"appearance\":\"棕色、棕褐色、灰色、炭色和岩石赭色的水平地层，具有不规则的纹理和嵌入的石块\"},\"callouts\":{\"count\":4,\"items\":[{\"position\":\"城市上方左侧\",\"text\":\"{argument name=\\\"top caption\\\" default=\\\"这里是大阪·新世界 通天阁的正下方\\\"}\",\"style\":\"带有棕色边框的奶油色对话框，带有爪印装饰，向下箭头\"},{\"position\":\"小猫上方中心\",\"text\":\"{argument name=\\\"main underground caption\\\" default=\\\"通天阁正下方\\\"}\",\"style\":\"带有粉色标题文字的奶油色标签，带有爪印，粗箭头指向小猫\"},{\"position\":\"右下角\",\"text\":\"{argument name=\\\"bottom caption\\\" default=\\\"好像一直在很深的地方睡觉呢……\\\"}\",\"style\":\"带有爪印的小型圆角奶油色对话框\"},{\"position\":\"小猫左侧附近\",\"text\":\"嗯……？\",\"style\":\"粉色手写体苏醒音效\"}]},\"underground_signs\":{\"count\":4,\"items\":[\"左墙标志：大深度地下 约 -70m 还在大阪的下面！\",\"黑板标志：通天阁直下 MAP，带有简单的塔楼图示和红色目标标记\",\"储物箱标签：地下探险 最喜欢了\",\"中心塔楼标志：通天阁\"]}},\"lighting\":{\"surface\":\"晴朗的白天，清澈的蓝天\",\"underground\":\"温暖的琥珀色灯笼光，柔和的阴影，与黑暗岩石形成对比的舒适光芒\"},\"camera\":\"正视正射投影信息图视角，洞穴内有轻微的绘本透视感，无极端畸变\",\"quality\":\"清晰易读的排版，纹理丰富的岩石和城市细节，迷人且精致的动漫插画，适合海报印刷的构图\"}","imgs":["https://r2.qqsrc.com/images/originals/17931.jpg"]},{"i":9989,"text":"以提供的参考图为基础，重现这只西施犬，并将其制作成一张色彩自然、清晰的照片。去除电话卡边框、印刷数字、文字、划痕、变色以及任何遮挡物或马赛克。将原有的卡片/照片背景替换为阳光明媚的户外公园场景：狗狗躺在翠绿的草地上，远处是柔和模糊的树木和温暖的阳光。保持狗狗居中并面向镜头，姿势与原图相似，同时保留其黑白毛色图案和两个黑色发结。提升图像质量，使其呈现出清晰的现代宠物肖像风格，具备逼真的毛发细节、自然光影和浅景深效果。","imgs":["https://r2.qqsrc.com/images/originals/17932.jpg"]},{"i":9990,"text":"在纯黑色背景上创作一张生动的动漫风格插画，主角是一位漂浮的天使少女，留着 {argument name=\"hair color\" default=\"柔和粉色\"} 的波波头，配有齐刘海，拥有柔和的粉色双眸，表情羞涩且略带嘟嘴。她穿着一件 {argument name=\"jacket color\" default=\"泡泡糖粉色\"} 的拉链运动夹克，袖子上有白色条纹，搭配白色短百褶裙、膝上白色长袜（袜口处有两条粉色条纹），以及厚底的柔和粉色系带运动鞋。让她呈现出半空中坐姿，一膝抬起，另一条腿向下弯曲，一只手靠近嘴边，另一只手向外伸展。在她身后添加两只白色羽翼，头顶上方添加一个正在融化的奶油粉色光环，并带有光泽滴落效果。用梦幻般的霓虹糖果空间氛围环绕她：左下方放置一颗带环的小行星，三个醒目的滴落状黄粉色星星挂饰，两团蓬松的粉紫色云朵，以及粉色、薄荷绿、青色和薰衣草紫色的柔和丝带轨迹围绕在她的身体周围。使用高饱和度的可爱赛博流行色彩，粗线条且干净的动漫勾线，带有绿色和洋红色的虹彩像差轮廓，闪亮的高光，零星散布的小火花，以及在黑色背景下具有高对比度的贴纸式构图。整体氛围应可爱、空灵、充满魔力且略带超现实感，宛如一位柔和系天使漂浮在糖果色的银河之中。","imgs":["https://r2.qqsrc.com/images/originals/17933.jpg"]},{"i":9991,"text":"创作一张可爱的 Q 版动漫贴纸插画，主角是 {argument name=\"character name\" default=\"一位困倦的天使女孩\"}，悬浮在平整明亮的 {argument name=\"background color\" default=\"天蓝色\"} 背景前。角色拥有白皙的皮肤、半睁的青色眼眸、小巧的中性嘴巴，以及长长的 {argument name=\"hair color\" default=\"浅金色\"} 双马尾，配有齐刘海和修饰脸型的发丝，并用 2 个黑色大蝴蝶结扎起。她的头顶上方有一个厚实的金色滴落状光环，周围环绕着 3 颗金色小闪星。她的背后有 2 对白色羽毛小天使翅膀。为她穿上一件超大号的 {argument name=\"jacket color\" default=\"青绿色\"} 拉链运动外套，配有高领、银色拉链和袖子上的两条白色条纹，下身搭配一条黑色短款百褶裙。让她呈现坐姿悬浮在半空中，一只膝盖抬起，另一条腿自然下垂，姿态略显慵懒，表情困倦。她穿着带有黑色横条纹的白色过膝袜，以及配有 {argument name=\"shoelace color\" default=\"黄色\"} 鞋带的白色运动鞋。采用干净的卡哇伊数字艺术风格，线条粗黑，形状圆润简洁，色彩平涂柔和，阴影极少，无文字，构图居中，全身可见，具有俏皮的吉祥物比例。","imgs":["https://r2.qqsrc.com/images/originals/17934.jpg"]},{"i":9992,"text":"创作一幅温馨的正方形动漫插画，背景是日落时分的河畔草坡。画面中共有 3 位 Q 版天使女孩并排坐在坡上，双膝抱胸，面向前方，有着小小的豆豆眼和温柔的微笑。每位女孩头顶上方都有一个发光的头环，背部有一对小巧的白色翅膀，总计 3 个头环和 3 对翅膀。左侧女孩拥有 {argument name=\"left character hair color\" default=\"长长的水蓝色头发\"}，身穿带有白色条纹的青色拉链运动夹克、深色百褶裙、条纹过膝袜和青色点缀的运动鞋。中间女孩拥有 {argument name=\"middle character hair color\" default=\"系着黑色丝带的长金发双马尾\"}，身穿带有白色条纹的深绿色拉链运动夹克、黑色百褶裙、条纹过膝袜和黄色点缀的运动鞋。右侧女孩拥有 {argument name=\"right character hair color\" default=\"长长的粉色头发\"}，身穿带有白色条纹的珊瑚粉拉链运动夹克、白色百褶裙、条纹过膝袜和粉色点缀的运动鞋。采用可爱且线条柔和的 2D 动漫风格，呈现温暖怀旧的灯光、圆润的比例、干净的轮廓，以及点缀着小白雏菊的细腻草地纹理。背景左侧包含一段通往坡上的阶梯，右侧是倒映着橙色太阳的平静河流，远处有一座桥梁，以及在桃橙色天空和零星蓬松云朵下的城市天际线。整体氛围应宁静、奇幻且略带魔力，太阳低垂在地平线附近，草地和水面上闪烁着温暖的金色光芒。","imgs":["https://r2.qqsrc.com/images/originals/17935.jpg"]},{"i":9993,"text":"{\"type\":\"用于鞋履推广的高影响力日语社交媒体宣传图\",\"canvas\":\"1:1 正方形布局，光泽感黑色奢华背景，配以橙金色霓虹线条、火花、镜头光晕、金属光泽，高端电商广告风格，戏剧性的产品布光，锐利逼真的鞋履产品结合醒目的排版\",\"brand\":\"{argument name=\\\"brand name\\\" default=\\\"ValueWalk\\\"}\",\"main_text\":{\"top_ribbon\":\"{argument name=\\\"campaign header\\\" default=\\\"在线商店及自有媒体上线纪念\\\"}\",\"headline\":\"{argument name=\\\"main headline\\\" default=\\\"商务鞋，还是休闲鞋\\\"}\",\"emphasis\":\"{argument name=\\\"emphasis text\\\" default=\\\"随心选！\\\"}\",\"subline\":\"FORMAL / CASUAL\",\"center_badge\":\"可选择喜欢的款式和尺码\",\"bottom_cta\":\"{argument name=\\\"call to action\\\" default=\\\"详情请查看置顶帖 ▶\\\"}\"},\"layout\":{\"top\":\"细橙色霓虹六边形丝带边框，内含活动标题，下方居中放置优雅的白色衬线体 ValueWalk 标志\",\"center\":\"巨大的粗体日语标题（白色），后跟超大号金橙色强调文字，带有 3D 光泽和发光效果；在下方以小型衬线字体标注 FORMAL / CASUAL，并用斜杠分隔\",\"product_count\":8,\"products\":[{\"position\":\"左上\",\"description\":\"穿着抛光棕色皮革商务正装鞋的局部脚部特写，搭配米色裤腿\"},{\"position\":\"右上\",\"description\":\"穿着黑色休闲运动鞋的局部脚部特写，配有厚白色鞋底和米色裤腿\"},{\"position\":\"左下大型主推产品\",\"description\":\"棕色皮革盖头系带正装鞋，光泽饰面，黑色鞋底，四分之三侧视图\"},{\"position\":\"右下大型主推产品\",\"description\":\"黑色低帮休闲运动鞋，带有穿孔鞋头，黑色鞋带，乳白色鞋底，四分之三侧视图\"},{\"position\":\"左下嵌入项 1\",\"description\":\"黑色正装鞋\"},{\"position\":\"左下嵌入项 2\",\"description\":\"黑色正装鞋\"},{\"position\":\"左下嵌入项 3\",\"description\":\"棕色正装鞋\"},{\"position\":\"左下嵌入项 4\",\"description\":\"黑色正装鞋\"}],\"inset_sections_count\":3,\"inset_sections\":[{\"position\":\"左下\",\"description\":\"金色轮廓矩形产品嵌入框，展示橙色 ValueWalk 鞋盒前的 4 双正装鞋\",\"item_count\":4},{\"position\":\"底部中央\",\"description\":\"圆形黑色徽章，带有粗金色霓虹环和堆叠的白/金日语文字\",\"item_count\":1},{\"position\":\"右下\",\"description\":\"金色轮廓矩形产品嵌入框，展示橙色 ValueWalk 鞋盒前的 4 双休闲运动鞋：海军蓝/黑色运动鞋、白色运动鞋、黑色运动鞋、黑色运动鞋\",\"item_count\":4}],\"bottom\":\"宽大的橙色渐变箭头状行动呼吁横幅，带有金色轮廓、明亮的内部发光效果、白色粗体日语文字和一个向右的三角形箭头\"},\"style\":\"高端零售活动，黑金配色方案配以橙色点缀，电影级对比度，逼真的皮革纹理，清晰的日语排版，精致的 SNS 广告，除局部脚踝外无人像，居中对称构图，文字清晰易读\"}","imgs":["https://r2.qqsrc.com/images/originals/17936.jpg"]},{"i":9994,"text":"以 REFERENCE_1 为素材源，提取下方意外拍摄的自拍照片并将其转化为最终的独立图像：彻底移除 ChatGPT 界面、文本气泡、下载图标和输入栏，然后对快照进行反裁剪/扩展，使其填满整个画面，呈现为竖屏 iPhone 风格的照片。遵循 REFERENCE_0 中描述的意图：使其看起来像是一张从口袋里掏出手机时无意间拍下的、略显失败的随意自拍，带有随意的低角度、杂乱的构图、轻微的运动模糊、不均匀的灯光、室内灯光造成的轻微过曝，以及非常真实的手机摄像头质感。保留下方照片中的室内环境、吸顶灯、壁灯和主体，但要展示出更多的面部、颈部、深色衬衫和细链项链，并在左下角前景处加入模糊的手指遮挡效果。避免使其看起来像是有意摆拍、经过精修、具有电影感或刻意构图的作品。","imgs":["https://r2.qqsrc.com/images/originals/17937.jpg"]},{"i":9995,"text":"使用 REFERENCE_0 作为源提示文本，REFERENCE_1 作为应用界面构图参考，生成最终的 ChatGPT 移动端对话界面。将日语提示词保留在右上角附近，作为一个小巧的灰色圆角消息气泡；在下方生成一张看起来像是从口袋里掏出手机时误触快门拍摄的普通自拍：画面应呈现凌乱的倾斜构图、轻微的运动模糊、不均匀的阳光眩光或过曝，且没有任何刻意的构图感。自拍背景设定在明亮日光的住宅区街道，画面右侧裁切掉了一名年轻女性的部分身影，她留着深色长发，前景中有一只穿着米色外套的袖子伸向镜头，背景是建筑物和蓝天。包含 ChatGPT 应用 UI：顶部栏带有汉堡菜单按钮、“ChatGPT”标题胶囊、撰写图标和三点菜单；在图片下方包含一个“編集する”编辑按钮和一个居中的向下箭头按钮。保持随意的非完美快照感，而非精致或电影级的画面。","imgs":["https://r2.qqsrc.com/images/originals/17938.jpg"]},{"i":9996,"text":"{\"type\":\"日式心理恐怖电影海报\",\"format\":\"竖版影院海报\",\"aspect_ratio\":\"2:3\",\"mood\":\"冰冷、压抑、诡异、电影感、潮湿的校园恐怖氛围\",\"setting\":{\"location\":\"古老的日本学校走廊\",\"time\":\"傍晚或阴天\",\"details\":\"狭长的走廊，布满污垢的混凝土墙面，磨损的地板，左侧是鞋柜和公告栏，右侧是布满雨痕的高大窗户，昏暗的吸顶荧光灯，深邃的阴影和蓝绿色调\"},\"composition\":{\"foreground\":\"一名身穿深色西装外套、白色衬衫和红色丝带领结的日本女高中生站在海报右侧近景处；齐肩黑色波波头，面部被一个平面的黑色方形遮挡，透着不安的静止感\",\"background\":\"走廊中后方偏左处有一个模糊的远景女学生剪影，部分背光且失焦\",\"lighting\":\"低调电影布光，窗边轮廓光，强暗角，空气中弥漫着尘埃，高对比度黑色\",\"camera\":\"肖像海报构图，浅景深，35mm 胶片质感，写实真人摄影风格\"},\"text_layout\":{\"count\":\"7 组独立文本\",\"groups\":[{\"position\":\"上方居中垂直\",\"text\":\"{argument name=\\\"vertical tagline\\\" default=\\\"わたしが ここに いる。\\\"}\",\"style\":\"纤细的日文竖排文字，以白色为主，其中“ここに”二字为柔和的红色\"},{\"position\":\"下方居中主标题\",\"text\":\"{argument name=\\\"movie title\\\" default=\\\"ふたり。\\\"}\",\"style\":\"巨大的粗犷手写日文书法，血红色，带有纹理并微微发光\"},{\"position\":\"标题下方\",\"text\":\"主演：一ノ瀬敦子（AIdol.1024）\",\"style\":\"小型白色衬线日文演职员表\"},{\"position\":\"中下方演职员行\",\"text\":\"出演：二宮陽菜（AIdol.1024）　日向ひより　緑馬のルイ三世　りなちゃんぴー（友情出演）\",\"style\":\"小型白色演职员表\"},{\"position\":\"下方演职员块\",\"text\":\"企画：between South Woods｜監督／脚本：阿里丹\\n制作会社：Building fictions｜撮影協力：南林間フィルムコミッション\\n音楽：Ail blocks｜撮影監督：風来坊\\n照明：Flava Light Works｜録音：Flarva Sound Design｜美術：FLOVA Art Lab｜編集：Flava Cut Studio\\nVFX：Flava Phantom Unit｜スタイリスト：Flava Closet｜ヘアメイク：FLOVA Beauty｜助監督：ふらぼ次郎\\n制作担当：フラバ太郎｜宣伝：Flava Trailer Dept.｜デザイン：FLOVA Graphics｜スチール：FLOVA Snap\\nキャスティング：Flava Cast｜音響効果：Flarva Sonic Creation｜特機：Flava Device Team\",\"style\":\"紧凑居中的微型白色制作人员名单，间或使用红色竖线分隔\"},{\"position\":\"底部居中\",\"text\":\"{argument name=\\\"release text\\\" default=\\\"今秋、劇場公開\\\"}\",\"style\":\"醒目的红色日文上映公告\"},{\"position\":\"底部角落\",\"text\":\"左侧：包含映伦和 PG12 的两个小型分级/格式框；右侧：配給：FLOVA PICTURES 及简约的白色发行商 Logo\",\"style\":\"真实的电影海报法律标识及发行商信息\"}]},\"typography\":\"日式恐怖海报排版，融合了优雅的白色明朝体演职员表与粗犷的红色书法字体；所有文字均像专业影院海报一样自然融合\",\"color_palette\":\"近乎黑色的阴影，去饱和的青灰色走廊，病态的青蓝色窗光，深绯红色的标题点缀，白色演职员表\",\"quality\":\"写实真人电影海报，高细节，逼真的日本独立恐怖片预告海报，除两名女学生外无额外人物，无血腥，非卡通风格\"}","imgs":["https://r2.qqsrc.com/images/originals/17939.jpg"]},{"i":9997,"text":"以 REFERENCE_0 作为角色设计基础，将该角色图转换为背景为 {argument name=\"background color\" default=\"纯白色\"} 的整洁 2D 游戏精灵图集。保留兔子角色的比例、黑色轮廓风格、蓝色耳内侧、蓝色眼睛、红色小鼻子和毛茸茸的尾巴，但需移除所有日语标签和参考图标题。生成 {argument name=\"sprite count\" default=\"57\"} 个独立的全身精灵图，以松散的网格排列，并在姿态之间留出透明间隔。包含以下可见行：6 个小型正面待机/表情精灵；8 个向右奔跑精灵；8 个向右奔跑/跨步精灵；4 个正面中性待机精灵；5 个正面可爱/握爪精灵；8 个困倦、悲伤、蹲伏和低能量精灵；6 个正面愉快/中性表情精灵；6 个动态奔跑或跳跃精灵；以及底部的 6 个可爱反应精灵，包括害羞、惊讶、羞涩、闭眼微笑、歪头和手捂嘴姿势。保持线条艺术简洁且一致，如同用于 {argument name=\"game type\" default=\"2D 平台游戏或休闲手游\"} 的手绘卡通精灵图集，每个精灵均需独立，且不包含阴影、道具、文字、边框或背景场景。","imgs":["https://r2.qqsrc.com/images/originals/17940.jpg"]},{"i":9998,"text":"创作一张随性、手绘风格的时尚街头素描，采用朴素的黑色墨水马克笔风格，背景为白色，画面中准确呈现 2 位高挑纤瘦的年轻女性，站在雨中霓虹闪烁的城市人行道上，背景为 {argument name=\"store name\" default=\"BALENCIAGA\"} 店面。在左上方写上醒目的手写单词 {argument name=\"store name\" default=\"BALENCIAGA\"}。左侧女性面部清晰可见，留着 {argument name=\"hair color\" default=\"亮金黄色\"} 的齐下巴短发并带有刘海，姿态放松且微倾，双腿修长，穿着高跟露趾凉鞋，身穿超大号黑色连帽衫或卫衣，胸前印有白色小字 {argument name=\"chest logo text\" default=\"BB BALENCIAGA\"}，下搭黑色短裙。右侧女性更高，留着黑色长辫或脏辫，面部呈刻意模糊的矩形，身穿超大号黑色拉链夹克和黑色短裙，双腿修长，穿着高跟露趾凉鞋，双手插兜，姿态随意。衣物主要以密集的黑色涂鸦填充，带有粗犷的白色高光和不规则的轮廓线。背景应包含左侧 5 个清晰可见的垂直城市招牌：一个带有黄色符号和红色方块的高大白色招牌，一个带有黄色字符的窄长黑色招牌，一个带有红色日文片假名 {argument name=\"red sign text\" default=\"カラオケ\"} 的白色招牌，一个类似交通灯的小型招牌（带有红/黄/绿标记），以及街边一个蓝色小招牌；在最右侧边缘再添加一个蓝白相间的小招牌。描绘湿漉漉的人行道，上面有红色、黄色、蓝色和灰色的反射波纹，远处有微小的行人，简单的建筑透视线，以及右侧极简的店面墙壁。保持构图的素描感、高级时尚感、抓拍感和不完美感，使用细黑线条，点缀少量色彩，并留出大量空白。","imgs":["https://r2.qqsrc.com/images/originals/17941.jpg"]},{"i":9999,"text":"{\"type\":\"为奢侈男士皮鞋品牌设计的优质 LINE 图文菜单图片\",\"canvas\":{\"aspect_ratio\":\"3:2 宽屏横向\",\"style\":\"深色奢华编辑摄影风格，写实产品静物，黑色与深棕色调，暖金色点缀，优雅的日文排版\",\"resolution\":\"高细节，简洁的商业设计\"},\"brand_header\":{\"position\":\"顶部居中\",\"background\":\"哑光黑色皮革质感\",\"logo\":\"品牌名称左上角的小型抽象暗金色徽标\",\"brand_name\":\"{argument name=\\\"brand name\\\" default=\\\"ValueWalk\\\"}\",\"brand_name_style\":\"柔和金色的大号精致衬线字体\",\"account_text\":\"{argument name=\\\"account text\\\" default=\\\"LINE公式アカウント\\\"}\",\"account_text_style\":\"品牌名称右侧较小的白色日文文本\",\"decoration\":\"顶部横跨的细长弧形金线，网格上方居中处饰有小金钻\"},\"layout\":{\"grid\":\"页眉下方 2 行 3 列的六个可点击菜单面板\",\"panel_count\":6,\"dividers\":\"细长的柔和金色垂直和水平分割线，交叉点处饰有小金钻\",\"text_style\":\"大号白色日文明朝体衬线标签，带有微妙阴影，每个标签下方有一条短细金线\",\"sections\":[{\"position\":\"左上\",\"label\":\"{argument name=\\\"product menu label\\\" default=\\\"商品を見る\\\"}\",\"visual\":\"深色表面上的一双抛光黑色牛津皮鞋，鞋头带有戏剧性的高光\"},{\"position\":\"中上\",\"label\":\"{argument name=\\\"shoe manual label\\\" default=\\\"靴のマニュアル\\\"}\",\"visual\":\"深色桌面上放着一本名为 SHOE CARE MANUAL 的黑色书籍、鞋油罐、深色布料和木质马毛刷\"},{\"position\":\"右上\",\"label\":\"{argument name=\\\"blog label\\\" default=\\\"ブログを読む\\\"}\",\"visual\":\"深色木桌上的黑色笔记本或记事本、优雅的钢笔以及放在托盘上的黑咖啡杯\"},{\"position\":\"左下\",\"label\":\"サイズガイド\",\"visual\":\"深色工作台上的木质鞋楦、卷尺、鞋拔或金属配件工具以及复古擦鞋工具\"},{\"position\":\"中下\",\"label\":\"初回特典クーポン\",\"visual\":\"写有 SPECIAL COUPON 和 10% OFF 的黑色高级优惠券卡，放置在带有深色缎带的黑色信封上\"},{\"position\":\"右下\",\"label\":\"お問い合わせ\",\"visual\":\"深色皮革笔记本上的黑色客户服务耳机，配有一支奢华钢笔，背景为温暖的模糊灯光\"}]},\"mood\":\"精致、阳刚、高端鞋履护理精品店，适用于 LINE 官方账号图文菜单\",\"composition_notes\":\"确保所有六个日文标签清晰且拼写准确，在面板内居中；避免杂乱；保持一致的深色照明和金色分割线\"}","imgs":["https://r2.qqsrc.com/images/originals/17942.jpg"]}];